    const foldM = foldPair(toUuid('cmd:mcp'), toUuid('cmd:metrics'))
    const foldR = foldPair(toUuid('cmd:metrics'), toUuid('cmd:mcp'))
    const catalog = quantumCliToolsCatalog(matrix, at)
