      anchor: 'local-session-hub', heading: 'Local from session',
      honestyLine: `metrics · ux=${localSessionUxImproved} · toolbox=${toolbox.total} · cards=${morph.analytics.cardCount} · linked=${morph.analytics.linkedCount} · gaps=${morph.analytics.gapCount} · dual=${morph.doubleSlit.waveParticleDual} · formula/code=${formulaCodeOk} · geo/train=${geoTrainOk} · analytics/self=${analyticsSelfObsOk}`,
