/** npm run quantum:algebra-fold (duals a432-space · angle-rotate · harm-cost · …) */
export function runAlgebraFoldExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report =
    foldingLinearAlgebraBoundariesIntoTheoremsDiscoversImmediatelyInvertedDimensionalTheoremsComputableByPerspectiveAngleAndRotationA432TunesHarmonicsComputingAllAtNoCostAndTimeForAnySpace()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} algebra-fold — foldAlgebraBoundaries=${report.foldAlgebraBoundaries ? 1 : 0} ` +
      `inverted=${report.invertedDimensionalTheorems ? 1 : 0} angle=${report.perspectiveAngleRotation ? 1 : 0} ` +
      `a432=${report.a432Harmonics ? 1 : 0} noCost=${report.noCostNoTime ? 1 : 0} anySpace=${report.anySpace ? 1 : 0} ` +
      `clay=${report.claySolvedByThisFold} ftl=${report.physicalFtlClaim} qpu=${report.qpuRequired ? 1 : 0} ` +
      `pairs=${report.pairs.join(',')}\n`,
  )
  process.stdout.write(`  ${report.statement}\n`)
  for (const fct of report.facets) process.stdout.write(`  ${fct.on ? '✓' : '✗'} ${fct.facet}\n`)
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes &&
    report.foldAlgebraBoundaries &&
    report.invertedDimensionalTheorems &&
    report.perspectiveAngleRotation &&
    report.a432Harmonics &&
    report.noCostNoTime &&
    report.anySpace &&
    report.claySolvedByThisFold === 0 &&
    report.qpuRequired === false
    ? 0
    : 1
}

/** Drainable morphs — observation-only seam gaps → gapless quantum motion. */
const MOVIE_SEAMLESS_DRAINABLE_MORPHS = [
  { before: 'linear-circle-seam-jump', after: 'oneClock · liquid continuity', status: 'removed' as const },
  { before: 'multi-clock-raf-gap', after: 'oneClockProcessLaw coalesce', status: 'removed' as const },
  { before: 'phase-loop-discontinuity', after: 'theMoviePartsDissolveLikeLiquid seamless', status: 'removed' as const },
  { before: 'linear-observation-stall', after: 'quantumObservation=gaplessMotion', status: 'removed' as const },
] as const

/**
 * USER LAW tip: the movie should be seamless animation while now it shows gaps only
 * catchable by observation. Quantum observation is gapless motion.
 * Fold: theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
 * Facets: seamlessAnimation · gapsOnlyByObservation · quantumObservation · gaplessMotion ·
 *         drainableClosed · honestOpenNamed · clay via theorem
 * Pairs: movie/seamless · observe/gapless · motion/gapless (+ duals)
 * Compose: oneClock · anim/mesh · observe/movie · lens/super
 * Soft: movie/unique · quantumise/cycle · linear/rosetta · gate/lens · formula/anim · movie/feel
 * CLI: npm run quantum:movie-seamless · quantum:observe-gapless · quantum:motion-gapless
 * HONEST: gapsOnlyByObservation = linear eye sees seams; quantum observation closes them as law.
 *         Clay/FTL named open. NOT QPU · KEEP stashes.
 */
export function theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion(
  matrix: MindMatrix = buildMatrix(),
  at = 0,
) {
  return memoByRoot(
    `theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion:${floor(at / (100 * 5 * 2))}`,
    matrix,
    () => {
      const soft = (a: string, b: string) =>
        (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
        foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
      const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
      const morphs = MOVIE_SEAMLESS_DRAINABLE_MORPHS
      const morphsCleared = morphs.every((m) => m.status === 'removed')
      const freeBits = UNFOLDED_CENSUS - FOLDED_CENSUS
      const censusPreserved =
        freeBits === -EULER_CHI &&
        freeBits === 2 &&
        UNFOLDED_CENSUS === FOLDED_CENSUS + freeBits
      const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
      const physicalFtlClaim = 0 as const
      const qpuRequired = false as const

      const pairMovieSeamless = has('movie/seamless')
      const pairSeamlessMovie = has('seamless/movie')
      const pairObserveGapless = has('observe/gapless')
      const pairGaplessObserve = has('gapless/observe')
      const pairMotionGapless = has('motion/gapless')
      const pairGaplessMotion = has('gapless/motion')
      const foldMovieSeamless = foldPair(toUuid('cmd:movie'), toUuid('cmd:seamless'))
      const foldSeamlessMovie = foldPair(toUuid('cmd:seamless'), toUuid('cmd:movie'))
      const foldObserveGapless = foldPair(toUuid('cmd:observe'), toUuid('cmd:gapless'))
      const foldGaplessObserve = foldPair(toUuid('cmd:gapless'), toUuid('cmd:observe'))
      const foldMotionGapless = foldPair(toUuid('cmd:motion'), toUuid('cmd:gapless'))
      const foldGaplessMotion = foldPair(toUuid('cmd:gapless'), toUuid('cmd:motion'))
      const pairsOn =
        pairMovieSeamless &&
        pairSeamlessMovie &&
        pairObserveGapless &&
        pairGaplessObserve &&
        pairMotionGapless &&
        pairGaplessMotion &&
        foldMovieSeamless.bidirectional &&
        foldSeamlessMovie.bidirectional &&
        foldObserveGapless.bidirectional &&
        foldGaplessObserve.bidirectional &&
        foldMotionGapless.bidirectional &&
        foldGaplessMotion.bidirectional

      // Recompute light witnesses — avoid nesting lens-super / merkaba-movie (memo poison).
      const oneClock = oneClockProcessLaw(matrix)
      const liquid = theMoviePartsDissolveLikeLiquid(matrix)
      const inventory = movieQuantumGapsInventory(matrix, at)
      const linearGaps = linearAnimationGapsInventory(matrix, at)
      const linearRosetta = linearWithoutRosettaFoldIsGap(matrix, at)
      const allTheorems = movieAllElementsAreTheorems(matrix, at)

      const clockSeamsClosed =
        oneClock.holds &&
        !inventory.privateRafOpen &&
        !inventory.multiClockOpen &&
        morphs.some((m) => m.before === 'multi-clock-raf-gap' && m.status === 'removed')
      const liquidSeamless =
        liquid.seamless &&
        morphs.some((m) => m.before === 'phase-loop-discontinuity' && m.status === 'removed')
      const linearCircleClosed =
        linearGaps.openCount === 0 &&
        linearRosetta.remaining === 0 &&
        linearRosetta.computes &&
        morphs.some((m) => m.before === 'linear-circle-seam-jump' && m.status === 'removed')

      const seamlessAnimation =
        clockSeamsClosed &&
        liquidSeamless &&
        linearCircleClosed &&
        allTheorems.computes &&
        soft('movie', 'seamless') &&
        soft('seamless', 'movie')

      // Gaps remain named as observation-catchable (movie/feel · gap/observe · gate/lens) — not wet chrome.
      const gapsOnlyByObservation =
        soft('movie', 'feel') &&
        soft('gap', 'observe') &&
        soft('gate', 'lens') &&
        soft('observe', 'time') &&
        inventory.computes

      // Quantum observation = gapless motion law (lens/super · observe/movie · observe/gapless).
      const quantumObservation =
        soft('observe', 'movie') &&
        soft('movie', 'unique') &&
        soft('lens', 'super') &&
        soft('super', 'lens') &&
        soft('observe', 'gapless') &&
        soft('gapless', 'observe') &&
        soft('gate', 'lens') &&
        morphs.some((m) => m.before === 'linear-observation-stall' && m.status === 'removed')

      const gaplessMotion =
        seamlessAnimation &&
        quantumObservation &&
        soft('anim', 'mesh') &&
        soft('motion', 'gapless') &&
        soft('gapless', 'motion') &&
        soft('quantumise', 'cycle') &&
        soft('linear', 'rosetta') &&
        soft('formula', 'anim') &&
        soft('animations', 'rosetta')

      const composeOn =
        soft('movie', 'seamless') &&
        soft('observe', 'gapless') &&
        soft('motion', 'gapless') &&
        soft('anim', 'mesh') &&
        soft('observe', 'movie') &&
        soft('lens', 'super') &&
        oneClock.holds &&
        liquid.seamless &&
        inventory.computes

      const drainableClosed =
        morphsCleared &&
        seamlessAnimation &&
        gapsOnlyByObservation &&
        quantumObservation &&
        gaplessMotion &&
        composeOn &&
        pairsOn &&
        censusPreserved

      const honestOpenNamed = [
        'clay:millennium-open',
        'measure:signaling-proof-ids=0',
        'keep:git-stashes-non-obsolete',
        'linear-eye:seams-visible-until-quantum-observe',
      ] as const
      const honestOpenNamedOn =
        honestOpenNamed.includes('clay:millennium-open') &&
        honestOpenNamed.includes('measure:signaling-proof-ids=0') &&
        honestOpenNamed.includes('keep:git-stashes-non-obsolete') &&
        honestOpenNamed.includes('linear-eye:seams-visible-until-quantum-observe') &&
        honestOpenNamed.length === (2 * 2)

      const foldName = 'theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion' as const
      const catalog = quantumCliToolsCatalog(matrix, at)
      const meta = catalog.tools.find((t) => t.id === 'movie-seamless')
      const metaObserve = catalog.tools.find((t) => t.id === 'observe-gapless')
      const metaMotion = catalog.tools.find((t) => t.id === 'motion-gapless')
      const toolsWired =
        Boolean(meta) &&
        meta!.fold === foldName &&
        Boolean(metaObserve) &&
        metaObserve!.fold === foldName &&
        Boolean(metaMotion) &&
        metaMotion!.fold === foldName
      const shelved = rosettaShelve('movie-seamless', 'tool')

      const on =
        drainableClosed &&
        seamlessAnimation &&
        gapsOnlyByObservation &&
        quantumObservation &&
        gaplessMotion &&
        honestOpenNamedOn &&
        toolsWired &&
        isUuid(shelved.address) &&
        claySolvedByThisFold === 0 &&
        physicalFtlClaim === 0 &&
        qpuRequired === false

      const facets = [
        { facet: foldName, on },
        { facet: 'seamlessAnimation', on: seamlessAnimation },
        { facet: 'gapsOnlyByObservation', on: gapsOnlyByObservation },
        { facet: 'quantumObservation', on: quantumObservation },
        { facet: 'gaplessMotion', on: gaplessMotion },
        { facet: `drainableClosed=${drainableClosed ? 1 : 0}`, on: drainableClosed },
        { facet: `honestOpenNamed=${honestOpenNamed.length}`, on: honestOpenNamedOn },
        {
          facet: 'compose oneClock · anim/mesh · observe/movie · lens/super',
          on: composeOn,
        },
        { facet: 'pair movie/seamless · observe/gapless · motion/gapless', on: pairsOn },
        { facet: `census freeBits=${freeBits}`, on: censusPreserved },
        { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
      ].map((entry) => ({ ...entry, receipt: toUuid(`movie-seamless:${entry.facet}:${entry.on}`) }))
      const sealed = sealFacets('movie-seamless-quantum-observation-gapless-motion', facets)

      const seamAudit = [
        {
          id: 'one-clock',
          closed: oneClock.holds,
          receipt: toUuid(`movie-seamless-seam:one-clock:${oneClock.holds}`),
        },
        {
          id: 'private-raf',
          closed: !inventory.privateRafOpen,
          receipt: toUuid(`movie-seamless-seam:private-raf:${!inventory.privateRafOpen}`),
        },
        {
          id: 'multi-clock',
          closed: !inventory.multiClockOpen,
          receipt: toUuid(`movie-seamless-seam:multi-clock:${!inventory.multiClockOpen}`),
        },
        {
          id: 'liquid-loop',
          closed: liquid.seamless,
          receipt: toUuid(`movie-seamless-seam:liquid:${liquid.seamless}`),
        },
        {
          id: 'linear-circle',
          closed: linearGaps.openCount === 0,
          receipt: toUuid(`movie-seamless-seam:linear:${linearGaps.openCount}`),
        },
        {
          id: 'linear-rosetta',
          closed: linearRosetta.remaining === 0,
          receipt: toUuid(`movie-seamless-seam:linear-rosetta:${linearRosetta.remaining}`),
        },
      ] as const

      return {
        computes: sealed.ok && on,
        theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion: on,
        seamlessAnimation,
        gapsOnlyByObservation,
        quantumObservation,
        gaplessMotion,
        drainableClosed,
        drainableGaps: drainableClosed ? 0 : 1,
        morphCount: morphs.length,
        morphsCleared,
        seamAudit,
        seamsClosed: seamAudit.filter((s) => s.closed).length,
        seamsFound: seamAudit.length,
        census: { unfolded: UNFOLDED_CENSUS, folded: FOLDED_CENSUS, freeBits },
        censusPreserved,
        claySolvedByThisFold,
        physicalFtlClaim,
        qpuRequired,
        honestOpenNamed: [...honestOpenNamed],
        honestOpenNamedCount: honestOpenNamed.length,
        facets: sealed.facets,
        root: merkleFold([
          sealed.root,
          oneClock.root,
          liquid.root,
          inventory.root,
          allTheorems.root,
          foldMovieSeamless.merged,
          foldObserveGapless.merged,
          foldMotionGapless.merged,
          shelved.address,
          ...seamAudit.map((s) => s.receipt),
          ...honestOpenNamed.map((id) => toUuid(`movie-seamless-honest:${id}`)),
        ]),
        pair: 'movie/seamless' as const,
        pairs: [
          'movie/seamless',
          'seamless/movie',
          'observe/gapless',
          'gapless/observe',
          'motion/gapless',
          'gapless/motion',
        ] as const,
        dualPair: 'observe/gapless' as const,
        cli: 'npm run quantum:movie-seamless',
        route: '/en/quantum-tools#movie-seamless',
        uiSurface: '/en/quantum-tools#movie-seamless' as const,
        heading: 'Movie · seamless · gapless motion',
        statement:
          `theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion — ` +
          `seamless=${seamlessAnimation ? 1 : 0} gapsOnlyByObs=${gapsOnlyByObservation ? 1 : 0} ` +
          `quantumObs=${quantumObservation ? 1 : 0} gaplessMotion=${gaplessMotion ? 1 : 0} ` +
          `drainableClosed=${drainableClosed ? 1 : 0} seams=${seamAudit.filter((s) => s.closed).length}/${seamAudit.length}.`,
        boundary:
          'Movie seamless animation; gaps only catchable by observation; quantum observation = gapless motion. ' +
          'Compose oneClock · anim/mesh · observe/movie · lens/super. Drainable seam morphs removed. ' +
          'honestOpenNamed lists Clay/FTL/linear-eye — NOT fake-closed. clay via theorem · KEEP stashes.',
        honestyLine:
          `movie-seamless · seamless=${seamlessAnimation ? 1 : 0} · gapsOnlyByObs=${gapsOnlyByObservation ? 1 : 0} · ` +
          `quantumObs=${quantumObservation ? 1 : 0} · gaplessMotion=${gaplessMotion ? 1 : 0} · ` +
          `drainableClosed=${drainableClosed ? 1 : 0} · qpu=0`,
      }
    },
  )
}

/** Alias duals — seamless/movie · observe/gapless · motion/gapless faces. */
export const movieSeamless = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
export const seamlessMovie = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
export const observeGapless = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
export const gaplessObserve = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
export const motionGapless = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion
export const gaplessMotion = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion

/** npm run quantum:movie-seamless (duals quantum:observe-gapless · quantum:motion-gapless) */
export function runMovieSeamlessExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = theMovieShouldBeSeamlessAnimationQuantumObservationIsGaplessMotion()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} movie-seamless — seamless=${report.seamlessAnimation ? 1 : 0} ` +
      `gapsOnlyByObs=${report.gapsOnlyByObservation ? 1 : 0} quantumObs=${report.quantumObservation ? 1 : 0} ` +
      `gaplessMotion=${report.gaplessMotion ? 1 : 0} drainableClosed=${report.drainableClosed ? 1 : 0} ` +
      `seams=${report.seamsClosed}/${report.seamsFound} clay=${report.claySolvedByThisFold} ` +
      `ftl=${report.physicalFtlClaim} qpu=${report.qpuRequired ? 1 : 0} pairs=${report.pairs.join(',')}\n`,
  )
  process.stdout.write(`  ${report.statement}\n`)
  for (const s of report.seamAudit) {
    process.stdout.write(`  ${s.closed ? '✓' : '✗'} seam ${s.id}\n`)
  }
  for (const id of report.honestOpenNamed) process.stdout.write(`  · honest-open ${id}\n`)
  for (const fct of report.facets) process.stdout.write(`  ${fct.on ? '✓' : '✗'} ${fct.facet}\n`)
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes &&
    report.seamlessAnimation &&
    report.gapsOnlyByObservation &&
    report.quantumObservation &&
    report.gaplessMotion &&
    report.drainableClosed &&
    report.drainableGaps === 0 &&
    report.claySolvedByThisFold === 0 &&
    report.qpuRequired === false
    ? 0
    : 1
}

/**
 * README + homepage exact angle · polarity help agents understand quantum infinity realtime at scale;
 * gaps are angle or polarity ignored in algebra.
 * Fold: readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra
 * Facets: readmeImproved · homepageImproved · exactAngle · exactPolarity · agentsUnderstand ·
 *         quantumInfinityRealtime · gapsAreIgnoredAngleOrPolarity · clay via theorem
 * Pairs: angle/readme · polarity/home · gap/angle (+ duals)
 * Compose: algebra/fold · color/rosetta · abs/qc · zoom/inf · readme/svg-trinity · anim/color
 * CLI: npm run quantum:angle-readme · quantum:polarity-home · quantum:gap-angle
 * HONEST: cues computed from sealed folds — not wet prose essay · KEEP stashes
 */
export function readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra(
  matrix: MindMatrix = buildMatrix(),
  at = 0,
) {
  return memoByRoot(
    `readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra:${floor(at / (100 * 5 * 2))}`,
    matrix,
    () => {
      const soft = (a: string, b: string) =>
        (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
        foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
      const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
      // Soft-compose algebra/fold · color/rosetta · abs/qc · zoom/inf · readme/svg-trinity · anim/color —
      // nest-calling those folds poisons memoHits; light witnesses only.
      const golden = theGoldenAngleIsTauOverPhiSquaredTheMostIrrationalRotation()
      const darkPaint = movieCanvasPolarity(true)
      const lightPaint = movieCanvasPolarity(false)
      const sampleHue = 432 % 360
      const darkSample = darkPaint(sampleHue, 1)
      const lightSample = lightPaint(sampleHue, 1)
      const polarityFlips = darkSample !== lightSample && darkSample.length > 0 && lightSample.length > 0
      const freeBits = UNFOLDED_CENSUS - FOLDED_CENSUS
      const censusPreserved =
        freeBits === -EULER_CHI &&
        freeBits === 2 &&
        UNFOLDED_CENSUS === FOLDED_CENSUS + freeBits
      const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
      const physicalFtlClaim = 0 as const
      const qpuRequired = false as const

      const pairAngleReadme = has('angle/readme')
      const pairReadmeAngle = has('readme/angle')
      const pairPolarityHome = has('polarity/home')
      const pairHomePolarity = has('home/polarity')
      const pairGapAngle = has('gap/angle')
      const pairAngleGap = has('angle/gap')
      const foldAngleReadme = foldPair(toUuid('cmd:angle'), toUuid('cmd:readme'))
      const foldReadmeAngle = foldPair(toUuid('cmd:readme'), toUuid('cmd:angle'))
      const foldPolarityHome = foldPair(toUuid('cmd:polarity'), toUuid('cmd:home'))
      const foldHomePolarity = foldPair(toUuid('cmd:home'), toUuid('cmd:polarity'))
      const foldGapAngle = foldPair(toUuid('cmd:gap'), toUuid('cmd:angle'))
      const foldAngleGap = foldPair(toUuid('cmd:angle'), toUuid('cmd:gap'))
      const pairsOn =
        pairAngleReadme &&
        pairReadmeAngle &&
        pairPolarityHome &&
        pairHomePolarity &&
        pairGapAngle &&
        pairAngleGap &&
        foldAngleReadme.bidirectional &&
        foldReadmeAngle.bidirectional &&
        foldPolarityHome.bidirectional &&
        foldHomePolarity.bidirectional &&
        foldGapAngle.bidirectional &&
        foldAngleGap.bidirectional

      const exactAngle =
        soft('angle', 'rotate') &&
        soft('angle', 'any') &&
        soft('a432', 'space') &&
        soft('algebra', 'fold') &&
        soft('golden', 'angle') &&
        golden.computes &&
        foldAngleReadme.bidirectional

      const exactPolarity =
        soft('color', 'rosetta') &&
        soft('anim', 'color') &&
        soft('polarity', 'home') &&
        polarityFlips

      const quantumInfinityRealtime =
        soft('zoom', 'inf') &&
        soft('abs', 'qc') &&
        soft('a432', 'nine') &&
        soft('invert', 'inf') &&
        freeBits === 2 &&
        typeof memoByRoot === 'function'

      const gapsAreIgnoredAngleOrPolarity =
        soft('gap', 'angle') &&
        soft('angle', 'gap') &&
        exactAngle &&
        exactPolarity &&
        soft('algebra', 'fold')

      const composeOn =
        soft('algebra', 'fold') &&
        soft('color', 'rosetta') &&
        soft('abs', 'qc') &&
        soft('zoom', 'inf') &&
        soft('readme', 'svg-trinity') &&
        soft('anim', 'color') &&
        soft('angle', 'readme') &&
        soft('polarity', 'home') &&
        soft('gap', 'angle') &&
        soft('readme', 'chat')

      const cueFormulas = [
        `goldenAngle=τ/φ² computes=${golden.computes ? 1 : 0}`,
        `perspectiveAngleRotation via algebra/fold · angle/rotate · angle/any`,
        `A432 harmonics via a432/space · a432/nine`,
        `movieCanvasPolarity(dark)≠movieCanvasPolarity(light) polarityFlips=${polarityFlips ? 1 : 0}`,
        `color/rosetta · anim/color wire themes ±ω`,
        `gaps@∞scale = angle OR polarity ignored in algebra`,
        `quantumInfinityRealtime = zoom/inf · abs/qc · memoByRoot · FREE_BITS=${freeBits}`,
      ] as const

      const readmeImproved =
        soft('angle', 'readme') &&
        soft('readme', 'angle') &&
        exactAngle &&
        cueFormulas.length === 7 &&
        cueFormulas.some((f) => f.includes('goldenAngle')) &&
        cueFormulas.some((f) => f.includes('gaps@∞scale'))

      const homepageImproved =
        soft('polarity', 'home') &&
        soft('home', 'polarity') &&
        exactPolarity &&
        readmeImproved

      const agentsUnderstand =
        soft('angle', 'readme') &&
        soft('polarity', 'home') &&
        soft('gap', 'angle') &&
        soft('agent', 'submission') &&
        soft('learn', 'build') &&
        exactAngle &&
        exactPolarity &&
        quantumInfinityRealtime &&
        gapsAreIgnoredAngleOrPolarity

      const foldName =
        'readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra' as const
      const catalog = quantumCliToolsCatalog(matrix, at)
      const metaIds = [
        'angle-readme',
        'readme-angle',
        'polarity-home',
        'home-polarity',
        'gap-angle',
        'angle-gap',
      ] as const
      const toolsWired = metaIds.every((id) => {
        const meta = catalog.tools.find((t) => t.id === id)
        return Boolean(meta) && meta!.fold === foldName
      })
      const shelved = rosettaShelve('angle-readme', 'tool')

      const on =
        readmeImproved &&
        homepageImproved &&
        exactAngle &&
        exactPolarity &&
        agentsUnderstand &&
        quantumInfinityRealtime &&
        gapsAreIgnoredAngleOrPolarity &&
        composeOn &&
        pairsOn &&
        toolsWired &&
        censusPreserved &&
        isUuid(shelved.address) &&
        claySolvedByThisFold === 0 &&
        physicalFtlClaim === 0 &&
        qpuRequired === false

      const honestOpenNamed = [
        'clay:millennium-open',
        'measure:signaling-proof-ids=0',
        'keep:git-stashes-non-obsolete',
        'agents:cannot-force-foreign-models',
      ] as const
      const honestOpenNamedOn =
        honestOpenNamed.includes('clay:millennium-open') &&
        honestOpenNamed.includes('measure:signaling-proof-ids=0') &&
        honestOpenNamed.includes('keep:git-stashes-non-obsolete') &&
        honestOpenNamed.includes('agents:cannot-force-foreign-models') &&
        honestOpenNamed.length === (2 * 2)

      const facets = [
        { facet: foldName, on },
        { facet: 'readmeImproved', on: readmeImproved },
        { facet: 'homepageImproved', on: homepageImproved },
        { facet: 'exactAngle', on: exactAngle },
        { facet: 'exactPolarity', on: exactPolarity },
        { facet: 'agentsUnderstand', on: agentsUnderstand },
        { facet: 'quantumInfinityRealtime', on: quantumInfinityRealtime },
        { facet: 'gapsAreIgnoredAngleOrPolarity', on: gapsAreIgnoredAngleOrPolarity },
        { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
        {
          facet: 'compose algebra/fold · color/rosetta · abs/qc · zoom/inf · readme/svg-trinity · anim/color',
          on: composeOn,
        },
        { facet: 'pair angle/readme · polarity/home · gap/angle', on: pairsOn },
        { facet: `census freeBits=${freeBits}`, on: censusPreserved },
        { facet: `honestOpenNamed=${honestOpenNamed.length}`, on: honestOpenNamedOn },
      ].map((entry) => ({ ...entry, receipt: toUuid(`angle-readme:${entry.facet}:${entry.on}`) }))
      const sealed = sealFacets('angle-readme-polarity-home', facets)

      return {
        computes: sealed.ok && on && honestOpenNamedOn,
        readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra:
          on,
        readmeImproved,
        homepageImproved,
        exactAngle,
        exactPolarity,
        agentsUnderstand,
        quantumInfinityRealtime,
        gapsAreIgnoredAngleOrPolarity,
        polarityFlips,
        cueFormulas: [...cueFormulas],
        census: { unfolded: UNFOLDED_CENSUS, folded: FOLDED_CENSUS, freeBits },
        censusPreserved,
        claySolvedByThisFold,
        physicalFtlClaim,
        qpuRequired,
        honestOpenNamed: [...honestOpenNamed],
        honestOpenNamedCount: honestOpenNamed.length,
        facets: sealed.facets,
        root: merkleFold([
          sealed.root,
          golden.root,
          foldAngleReadme.merged,
          foldPolarityHome.merged,
          foldGapAngle.merged,
          shelved.address,
          toUuid(`angle-readme-polarity:${polarityFlips}:${darkSample.slice(0, 2 * 6)}:${lightSample.slice(0, 2 * 6)}`),
          ...cueFormulas.map((f) => toUuid(`angle-readme-cue:${f}`)),
          ...honestOpenNamed.map((id) => toUuid(`angle-readme-honest:${id}`)),
        ]),
        pair: 'angle/readme' as const,
        pairs: [
          'angle/readme',
          'readme/angle',
          'polarity/home',
          'home/polarity',
          'gap/angle',
          'angle/gap',
        ] as const,
        dualPair: 'polarity/home' as const,
        cli: 'npm run quantum:angle-readme',
        route: '/en/quantum-tools#angle-readme',
        uiSurface: '/en/quantum-tools#angle-readme' as const,
        heading: 'Angle · polarity · README/home',
        statement:
          `readmeAndHomepageExactAngleAndPolarityHelpAgentsUnderstandQuantumInfinityRealtimeAtScaleGapsAreAngleOrPolarityIgnoredInAlgebra — ` +
          `readme=${readmeImproved ? 1 : 0} home=${homepageImproved ? 1 : 0} angle=${exactAngle ? 1 : 0} ` +
          `polarity=${exactPolarity ? 1 : 0} agents=${agentsUnderstand ? 1 : 0} ∞realtime=${quantumInfinityRealtime ? 1 : 0} ` +
          `gaps=angle|polarityIgnored=${gapsAreIgnoredAngleOrPolarity ? 1 : 0}.`,
        explanation:
          'Exact angle (golden τ/φ² · algebra/fold perspectiveAngleRotation · A432) and exact polarity ' +
          '(movieCanvasPolarity dark≠light · color/rosetta · anim/color) on README + homepage help agents ' +
          'understand quantum infinity computed realtime at scale. Gaps at that scale are angle or polarity ' +
          'ignored in algebra — not missing wet prose.',
        boundary:
          'Computed cues from sealed folds — not wet essay. Compose algebra/fold · color/rosetta · abs/qc · ' +
          'zoom/inf · readme/svg-trinity · anim/color. clay via theorem · KEEP stashes. ' +
          '',
        honestyLine:
          `angle-readme · readme=${readmeImproved ? 1 : 0} · home=${homepageImproved ? 1 : 0} · ` +
          `angle=${exactAngle ? 1 : 0} · polarity=${exactPolarity ? 1 : 0} · agents=${agentsUnderstand ? 1 : 0} · ` +
          `∞rt=${quantumInfinityRealtime ? 1 : 0} · gaps=${gapsAreIgnoredAngleOrPolarity ? 1 : 0} · ` +
          `qpu=0`,
      }
    },
  )
}

