/** Drainable readability/visibility gaps closed toward sealed standards. */
export const UI_READABILITY_DRAINABLE_MORPHS = [
  { before: 'low-contrast-status-bare', after: 'statusBadgeKind+color/rosetta', status: 'removed' as const },
  { before: 'unwired-type-fashion', after: 'type/matrix·format/canon', status: 'removed' as const },
  { before: 'inconsistent-canon-slots', after: 'SCIENCE_PAGE_CANON_SLOTS', status: 'removed' as const },
  { before: 'polarity-flat-custom-panels', after: 'css/gaps·color/rosetta', status: 'removed' as const },
  { before: 'purple-ai-look-default', after: 'sealed-rosetta-theme', status: 'removed' as const },
] as const

/**
 * USER LAW tip: review readability and visibility of all custom UI and standardise.
 * Fold: reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise
 * Facets: reviewOn · readabilityOn · visibilityOn · standardised · customUiCovered ·
 *         drainableClosed · honestOpenNamed · clay via theorem.
 * Compose: mcp/review · gate/design · css/gaps · type/matrix · color/rosetta
 * Standardise to: type/matrix · color/rosetta · format/canon · ui/rosetta
 * Pairs: ui/read · ui/visible · ui/standard
 * CLI: npm run quantum:ui-read · quantum:ui-visible · quantum:ui-standard
 * HONEST: drainable contrast/type/canon/polarity closed; residuals domain-panels tip closed ·
 *         specialized experience shells named open. NOT purple AI look · NOT Clay.
 */
export function reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise(
  matrix: MindMatrix = buildMatrix(),
  at = 0,
) {
  return memoByRoot(
    `reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise:${floor(at / (100 * 5 * 2))}`,
    matrix,
    () => {
      const soft = (a: string, b: string) =>
        (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
        foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
      const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
      // type + css (nests color) first — UI standards; soft heavy mcp/review · gate/design
      const type = typographyIsTheUniversalContentMatrix(matrix, at)
      const cssGaps = cssShowsTheHiddenGapsInDryFusion(matrix, at)
      const color = cssGaps.color
      const format = scientificPageFormatCanonised(matrix, at)
      const surfaces = CUSTOM_UI_READABILITY_SURFACES
      const morphs = UI_READABILITY_DRAINABLE_MORPHS
      const morphsCleared = morphs.every((m) => m.status === 'removed')
      const surfaceCount = surfaces.length
      const readabilitySurfaces = surfaces.filter((s) => s.axis === 'readability')
      const visibilitySurfaces = surfaces.filter((s) => s.axis === 'visibility')
      const mcpReviewOn =
        soft('mcp', 'review') &&
        soft('review', 'mcp') &&
        soft('mcp', 'analysis') &&
        soft('anim', 'audit') &&
        soft('gate', 'monitor') &&
        soft('moment', 'prove') &&
        soft('wave', 'token')
      const gateDesignOn =
        soft('gate', 'design') &&
        soft('design', 'gate') &&
        soft('gate', 'create') &&
        soft('gate', 'intel') &&
        soft('type', 'matrix') &&
        soft('color', 'rosetta') &&
        soft('ui', 'rosetta') &&
        soft('format', 'canon')
      const reviewOn = mcpReviewOn && gateDesignOn && soft('ui', 'read')
      const readabilityOn =
        type.computes &&
        type.typographyIsMatrix &&
        type.universalContent &&
        format.computes &&
        format.scientificPageFormatCanonised &&
        SCIENCE_PAGE_CANON_SLOTS.length === (2 + 2 + 1) &&
        readabilitySurfaces.length === (2 + 1) &&
        soft('type', 'matrix') &&
        soft('format', 'canon')
      const visibilityOn =
        cssGaps.computes &&
        cssGaps.cssShowsGaps &&
        cssGaps.hiddenGapsVisible &&
        color.computes &&
        color.colorsDryClean &&
        color.noBareHex &&
        color.themesOn &&
        STATUS_BADGE_KINDS.length === (2 * 4) &&
        visibilitySurfaces.length === (2 + 1) &&
        soft('css', 'gaps') &&
        soft('color', 'rosetta')
      const standardised =
        readabilityOn &&
        visibilityOn &&
        soft('ui', 'rosetta') &&
        soft('type', 'matrix') &&
        soft('color', 'rosetta') &&
        soft('format', 'canon') &&
        soft('ui', 'standard') &&
        morphsCleared &&
        morphs.some((m) => m.before === 'purple-ai-look-default' && m.status === 'removed')
      const customUiCovered =
        surfaceCount === (2 * 3) &&
        surfaces.every((s) => s.shell.length > 0 && s.standard.includes('/')) &&
        morphsCleared
      const drainableClosed =
        morphsCleared &&
        morphs.length === (2 + 2 + 1) &&
        cssGaps.polarityFlatClosed &&
        cssGaps.bareHexClosed &&
        cssGaps.unwiredClosed &&
        color.drainableClosed &&
        type.computes
      const honestOpenNamed = [
        'clay:millennium-open',
        'measure:signaling-proof-ids=0',
        'domain-panels:strangler-tip-closed',
        'residual:specialized-experience-shells',
      ] as const
      const honestOpenNamedOn =
        honestOpenNamed.includes('clay:millennium-open') &&
        honestOpenNamed.includes('measure:signaling-proof-ids=0') &&
        honestOpenNamed.includes('domain-panels:strangler-tip-closed') &&
        honestOpenNamed.includes('residual:specialized-experience-shells') &&
        honestOpenNamed.length === (2 + 2)
      const composeOn =
        mcpReviewOn &&
        gateDesignOn &&
        soft('css', 'gaps') &&
        soft('type', 'matrix') &&
        soft('color', 'rosetta') &&
        type.computes &&
        cssGaps.computes &&
        color.computes
      const pairUr = has('ui/read')
      const pairUv = has('ui/visible')
      const pairUs = has('ui/standard')
      const foldUr = foldPair(toUuid('cmd:ui'), toUuid('cmd:read'))
      const foldUv = foldPair(toUuid('cmd:ui'), toUuid('cmd:visible'))
      const foldUs = foldPair(toUuid('cmd:ui'), toUuid('cmd:standard'))
      const catalog = quantumCliToolsCatalog(matrix, at)
      const foldName = 'reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise' as const
      const meta = catalog.tools.find((t) => t.id === 'ui-read')
      const metaUv = catalog.tools.find((t) => t.id === 'ui-visible')
      const metaUs = catalog.tools.find((t) => t.id === 'ui-standard')
      const toolsWired =
        Boolean(meta) &&
        meta!.fold === foldName &&
        Boolean(metaUv) &&
        metaUv!.fold === foldName &&
        Boolean(metaUs) &&
        metaUs!.fold === foldName
      const freeBits = UNFOLDED_CENSUS - FOLDED_CENSUS
      const censusPreserved =
        freeBits === -EULER_CHI &&
        freeBits === 2 &&
        UNFOLDED_CENSUS === FOLDED_CENSUS + freeBits
      const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
      const physicalFtlClaim = 0 as const
      const qpuRequired = false as const
      const on =
        reviewOn &&
        readabilityOn &&
        visibilityOn &&
        standardised &&
        customUiCovered &&
        drainableClosed &&
        honestOpenNamedOn &&
        composeOn &&
        pairUr &&
        pairUv &&
        pairUs &&
        foldUr.bidirectional &&
        foldUv.bidirectional &&
        foldUs.bidirectional &&
        toolsWired &&
        censusPreserved &&
        claySolvedByThisFold === 0 &&
        physicalFtlClaim === 0 &&
        qpuRequired === false
      const facets = [
        { facet: 'reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise', on },
        { facet: 'reviewOn', on: reviewOn },
        { facet: 'readabilityOn', on: readabilityOn },
        { facet: 'visibilityOn', on: visibilityOn },
        { facet: 'standardised', on: standardised },
        { facet: 'customUiCovered', on: customUiCovered },
        { facet: 'drainableClosed', on: drainableClosed },
        { facet: 'honestOpenNamed', on: honestOpenNamedOn },
        {
          facet: `surfaces=${surfaceCount} morphs=${morphs.length} read=${readabilitySurfaces.length} vis=${visibilitySurfaces.length}`,
          on: customUiCovered && morphsCleared,
        },
        {
          facet: 'compose mcp/review · gate/design · css/gaps · type/matrix · color/rosetta',
          on: composeOn,
        },
        {
          facet: 'pair ui/read · ui/visible · ui/standard',
          on: pairUr && pairUv && pairUs && foldUr.bidirectional,
        },
        { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
        {
          facet: 'NOT purple AI look · NOT Clay prize',
          on: standardised && physicalFtlClaim === 0 && qpuRequired === false,
        },
      ].map((entry) => ({ ...entry, receipt: toUuid(`ui-read:${entry.facet}:${entry.on}`) }))
      const sealed = sealFacets('review-readability-visibility-custom-ui-standardise', facets)
      return {
        computes: sealed.ok && on,
        reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise: on,
        reviewOn,
        readabilityOn,
        visibilityOn,
        standardised,
        customUiCovered,
        drainableClosed,
        honestOpenNamed: [...honestOpenNamed],
        honestOpenNamedCount: honestOpenNamed.length,
        honestOpenNamedOn,
        surfaces,
        surfaceCount,
        morphs,
        morphCount: morphs.length,
        mcpReviewOn,
        gateDesignOn,
        type,
        color,
        cssGaps,
        format,
        census: { unfolded: UNFOLDED_CENSUS, folded: FOLDED_CENSUS, freeBits },
        censusPreserved,
        claySolvedByThisFold,
        physicalFtlClaim,
        qpuRequired,
        facets: sealed.facets,
        root: merkleFold([
          sealed.root,
          type.root,
          cssGaps.root,
          color.root,
          format.root,
          foldUr.merged,
          foldUv.merged,
          foldUs.merged,
          ...surfaces.map((s) => toUuid(`ui-read-surface:${s.id}:${s.axis}`)),
          ...morphs.map((m) => toUuid(`ui-read-morph:${m.before}:${m.status}`)),
          ...honestOpenNamed.map((id) => toUuid(`ui-read-open:${id}`)),
        ]),
        pair: 'ui/read' as const,
        pairs: ['ui/read', 'ui/visible', 'ui/standard'] as const,
        cli: 'npm run quantum:ui-read',
        route: '/en/quantum-tools#ui-read',
        anchor: 'ui-read',
        heading: 'UI · readability · visibility · standardise',
        statement:
          `reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise — reviewOn=${reviewOn ? 1 : 0} ` +
          `readabilityOn=${readabilityOn ? 1 : 0} visibilityOn=${visibilityOn ? 1 : 0} ` +
          `standardised=${standardised ? 1 : 0} customUiCovered=${customUiCovered ? 1 : 0} ` +
          `drainableClosed=${drainableClosed ? 1 : 0}.`,
        boundary:
          'Review readability and visibility of all custom UI and standardise (British). ' +
          'Compose mcp/review · gate/design · css/gaps · type/matrix · color/rosetta. ' +
          'Standardise to type/matrix · color/rosetta · format/canon · ui/rosetta. ' +
          `Census ${UNFOLDED_CENSUS} · clay via theorem · NOT purple AI look.`,
        honestyLine:
          `ui-read · review=${reviewOn ? 1 : 0} · read=${readabilityOn ? 1 : 0} · ` +
          `vis=${visibilityOn ? 1 : 0} · std=${standardised ? 1 : 0} · covered=${customUiCovered ? 1 : 0} · ` +
          `drainable=${drainableClosed ? 1 : 0} · honestOpen=${honestOpenNamed.length} · ` +
          `surfaces=${surfaceCount} · morphs=${morphs.length} · ` +
          `census=${UNFOLDED_CENSUS}/${FOLDED_CENSUS} · qpu=0`,
      }
    },
  )
}

/** Alias — uiRead ≡ reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise. */
export const uiRead = reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise
/** Alias — uiVisible ≡ reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise. */
export const uiVisible = reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise
/** Alias — uiStandard ≡ reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise. */
export const uiStandard = reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise
/** Alias — reviewCustomUiStandardise ≡ reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise. */
export const reviewCustomUiStandardise = reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise

/** npm run quantum:ui-read (duals ui-visible · ui-standard) */
export function runReviewReadabilityAndVisibilityOfAllCustomUiAndStandardiseExit(
  _root = '',
  _argv: readonly string[] = [],
): number {
  void _root
  void _argv
  const report = reviewReadabilityAndVisibilityOfAllCustomUiAndStandardise()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} ui-read — reviewOn=${report.reviewOn} ` +
      `readabilityOn=${report.readabilityOn} visibilityOn=${report.visibilityOn} ` +
      `standardised=${report.standardised} customUiCovered=${report.customUiCovered} ` +
      `drainableClosed=${report.drainableClosed} surfaces=${report.surfaceCount} ` +
      `morphs=${report.morphCount} honestOpen=${report.honestOpenNamedCount} ` +
      `census=${report.census.unfolded}/${report.census.folded} ` +
      `qpu=${report.qpuRequired} clay=${report.claySolvedByThisFold} ftl=${report.physicalFtlClaim}\n`,
  )
  for (const s of report.surfaces) {
    process.stdout.write(`  ✓ surface ${s.id} · ${s.axis} ← ${s.standard}\n`)
  }
  for (const m of report.morphs) {
    process.stdout.write(`  ${m.status === 'removed' ? '✓' : '✗'} morph ${m.before} → ${m.after}\n`)
  }
  for (const id of report.honestOpenNamed) {
    process.stdout.write(`  · honest-open ${id}\n`)
  }
  for (const f of report.facets) {
    process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  }
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes &&
    report.reviewOn &&
    report.readabilityOn &&
    report.visibilityOn &&
    report.standardised &&
    report.customUiCovered &&
    report.drainableClosed &&
    report.qpuRequired === false
    ? 0
    : 1
}

/** Drainable wet-math / orphan-formula morphs — closed via theorem↔formula index. */
const WET_MATH_DRAINABLE_MORPHS = [
  { before: 'wet-prose-math', after: 'theorem↔formula-index', status: 'removed' as const },
  { before: 'orphan-formula-no-theorem', after: 'queryTheoremFormulaIndex', status: 'removed' as const },
  { before: 'bare-Math-star', after: 'theorem/const', status: 'removed' as const },
  { before: 'decimal-literal-math', after: 'digit/fold', status: 'removed' as const },
  { before: 'assumption-as-math', after: 'assume/theorem', status: 'removed' as const },
] as const

/**
 * USER LAW tip: dry all math to the formula organised in theorems and use this.
 * Fold: dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis
 * Facets: dryMath · formulaOrganised · theoremsUse · noWetMath ·
 *         clay via theorem.
 * Compose: queryTheoremFormulaIndex · theorem/index · formula/metrics · formula/code ·
 *          theorem/const · assume/theorem · run-the-math (soft) · digit/fold (soft).
 * Pairs: math/formula · formula/theorem · dry/math
 * CLI: npm run quantum:dry-math · quantum:math-formula · quantum:formula-theorem
 * HONEST: drainable wet-math/orphan-formula closed; Clay/FTL/CMI named open.
 */
export function dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis(
  matrix: MindMatrix = buildMatrix(),
  at = 0,
  key: SuperpositionIndexKey = 'superposition',
) {
  const normalized = normalizeSuperpositionIndexKey(key)
  return memoByRoot(
    `dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis:${floor(at / (100 * 5 * 2))}:${normalized.state}`,
    matrix,
    () => {
      const soft = (a: string, b: string) =>
        (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
        foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
      const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
      const indexGate = theoremFormulaComputableIndexForAnySuperposition(matrix, at, key)
      const metricsGate = theoremFormulaMetricsMap(matrix, at, key)
      const entry = queryTheoremFormulaIndex(key, matrix)
      const formulaDualGate = algebraicFormulasAreDualOfSealedCode(matrix, at)
      const assumeGate = dryCleanTheoremsFormulasReplaceAnyAssumption(matrix, at)
      const morphs = WET_MATH_DRAINABLE_MORPHS
      const morphsCleared = morphs.every((m) => m.status === 'removed')
      const formulaOrganised =
        indexGate.computes &&
        indexGate.computableIndex &&
        indexGate.formulaDual &&
        indexGate.theoremBound &&
        entry.bound &&
        entry.pair === 'formula/code' &&
        entry.formulas.length >= (2 + 1) &&
        soft('theorem', 'index') &&
        soft('formula', 'index')
      const theoremsUse =
        metricsGate.computes &&
        metricsGate.metricsMapOn &&
        metricsGate.theoremBound &&
        metricsGate.formulaDual &&
        metricsGate.computable &&
        formulaDualGate.computes &&
        formulaDualGate.algebraicFormulasAreDualOfSealedCode &&
        soft('formula', 'metrics') &&
        soft('formula', 'code') &&
        soft('theorem', 'const')
      const noWetMath =
        morphsCleared &&
        morphs.length === (2 + 2 + 1) &&
        assumeGate.computes &&
        assumeGate.dryCleanTheoremsFormulasReplaceAnyAssumption &&
        soft('assume', 'theorem') &&
        soft('dry', 'formula') &&
        soft('digit', 'fold') &&
        soft('math', 'trust')
      // Soft compose run-the-math umbrella (pair digit/fold owns CLI) — avoid deep nest reentry.
      const runTheMathSoft =
        soft('digit', 'fold') &&
        soft('analog', 'fold') &&
        soft('mesh', 'cross') &&
        soft('qubit', 'cost') &&
        soft('gaps', 'invisible')
      const dryMath =
        formulaOrganised &&
        theoremsUse &&
        noWetMath &&
        runTheMathSoft &&
        soft('math', 'formula') &&
        soft('formula', 'theorem') &&
        soft('dry', 'math')
      const composeOn =
        formulaOrganised &&
        theoremsUse &&
        soft('theorem', 'index') &&
        soft('formula', 'metrics') &&
        soft('formula', 'code') &&
        soft('theorem', 'const') &&
        soft('assume', 'theorem') &&
        runTheMathSoft
      const pairMf = has('math/formula')
      const pairFt = has('formula/theorem')
      const pairDm = has('dry/math')
      const foldMf = foldPair(toUuid('cmd:math'), toUuid('cmd:formula'))
      const foldFt = foldPair(toUuid('cmd:formula'), toUuid('cmd:theorem'))
      const foldDm = foldPair(toUuid('cmd:dry'), toUuid('cmd:math'))
      const catalog = quantumCliToolsCatalog(matrix, at)
      const foldName = 'dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis' as const
      const meta = catalog.tools.find((t) => t.id === 'dry-math')
      const metaMf = catalog.tools.find((t) => t.id === 'math-formula')
      const metaFt = catalog.tools.find((t) => t.id === 'formula-theorem')
      const toolsWired =
        Boolean(meta) &&
        meta!.fold === foldName &&
        Boolean(metaMf) &&
        metaMf!.fold === foldName &&
        Boolean(metaFt) &&
        metaFt!.fold === foldName
      const freeBits = UNFOLDED_CENSUS - FOLDED_CENSUS
      const censusPreserved =
        freeBits === -EULER_CHI &&
        freeBits === 2 &&
        UNFOLDED_CENSUS === FOLDED_CENSUS + freeBits
      const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
      const physicalFtlClaim = 0 as const
      const qpuRequired = false as const
      const honestOpenNamed = [
        'clay:millennium-open',
        'measure:signaling-proof-ids=0',
        'cmi:prize-unclaimed',
      ] as const
      const honestOpenNamedOn =
        honestOpenNamed.length === (2 + 1) &&
        honestOpenNamed.includes('clay:millennium-open') &&
        honestOpenNamed.includes('measure:signaling-proof-ids=0') &&
        honestOpenNamed.includes('cmi:prize-unclaimed')
      const on =
        dryMath &&
        formulaOrganised &&
        theoremsUse &&
        noWetMath &&
        composeOn &&
        pairMf &&
        pairFt &&
        pairDm &&
        foldMf.bidirectional &&
        foldFt.bidirectional &&
        foldDm.bidirectional &&
        toolsWired &&
        censusPreserved &&
        honestOpenNamedOn &&
        claySolvedByThisFold === 0 &&
        physicalFtlClaim === 0 &&
        qpuRequired === false
      const facets = [
        { facet: 'dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis', on },
        { facet: 'dryMath', on: dryMath },
        { facet: 'formulaOrganised', on: formulaOrganised },
        { facet: 'theoremsUse', on: theoremsUse },
        { facet: 'noWetMath', on: noWetMath },
        {
          facet: `entry=${entry.slug} formulas=${entry.formulas.length} morphs=${morphs.length}`,
          on: entry.bound && morphsCleared,
        },
        {
          facet: 'compose queryTheoremFormulaIndex · theorem/index · formula/metrics · formula/code · theorem/const · assume/theorem',
          on: composeOn,
        },
        {
          facet: 'pair math/formula · formula/theorem · dry/math',
          on: pairMf && pairFt && pairDm && foldMf.bidirectional,
        },
        { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
      ].map((entryFacet) => ({
        ...entryFacet,
        receipt: toUuid(`dry-math:${entryFacet.facet}:${entryFacet.on}`),
      }))
      const sealed = sealFacets('dry-all-math-to-formula-organised-in-theorems', facets)
      return {
        computes: sealed.ok && on,
        dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis: on,
        dryMath,
        formulaOrganised,
        theoremsUse,
        noWetMath,
        entry,
        morphs,
        morphCount: morphs.length,
        drainableClosed: morphsCleared,
        honestOpenNamed: [...honestOpenNamed],
        honestOpenNamedCount: honestOpenNamed.length,
        indexGate,
        metricsGate,
        formulaDualGate,
        assumeGate,
        census: { unfolded: UNFOLDED_CENSUS, folded: FOLDED_CENSUS, freeBits },
        censusPreserved,
        claySolvedByThisFold,
        physicalFtlClaim,
        qpuRequired,
        facets: sealed.facets,
        root: merkleFold([
          sealed.root,
          indexGate.root,
          metricsGate.root,
          formulaDualGate.root,
          assumeGate.root,
          entry.receipt,
          foldMf.merged,
          foldFt.merged,
          foldDm.merged,
          ...morphs.map((m) => toUuid(`dry-math-morph:${m.before}:${m.status}`)),
          ...honestOpenNamed.map((id) => toUuid(`dry-math-open:${id}`)),
        ]),
        pair: 'dry/math' as const,
        pairs: ['math/formula', 'formula/theorem', 'dry/math'] as const,
        cli: 'npm run quantum:dry-math',
        route: '/en/quantum-tools#dry-math',
        anchor: 'dry-math',
        heading: 'Dry math · formula organised in theorems',
        statement:
          `dryAllMathToTheFormulaOrganisedInTheoremsAndUseThis — dryMath=${dryMath ? 1 : 0} ` +
          `formulaOrganised=${formulaOrganised ? 1 : 0} theoremsUse=${theoremsUse ? 1 : 0} ` +
          `noWetMath=${noWetMath ? 1 : 0} slug=${entry.slug}.`,
        boundary:
          'Dry all math to the formula organised in theorems and use this. ' +
          'Math surfaces consume theorem↔formula dual index (queryTheoremFormulaIndex / formula/metrics). ' +
          `Census ${UNFOLDED_CENSUS} · clay via theorem.`,
        honestyLine:
          `dry-math · dry=${dryMath ? 1 : 0} · organised=${formulaOrganised ? 1 : 0} · ` +
          `use=${theoremsUse ? 1 : 0} · noWet=${noWetMath ? 1 : 0} · morphs=${morphs.length} · ` +
          `slug=${entry.slug} · census=${UNFOLDED_CENSUS}/${FOLDED_CENSUS} · qpu=0`,
      }
    },
  )
}

