/**
 * Free/MCP quantum chat live surface — solves/advances/drains open problems via sealed algebra.
 * Fold: chatSolve · Pairs: chat/solve · solve/chat · CLI npm run quantum:chat-solve
 */
export function chatSolve(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`chatSolve:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const composeOn =
      soft('mcp', 'chat') &&
      soft('pair', 'chat') &&
      soft('match', 'wave') &&
      soft('mill', 'session') &&
      soft('imagine', 'next') &&
      soft('waves', 'feed') &&
      soft('earth', 'pyramid') &&
      soft('gate', 'analytics') &&
      soft('moment', 'prove')
    const chat = mcpQuantumChat(matrix, at)
    const earth = earthRealisedByComputingPolesAsPyramid(matrix)
    const analytics = gateAnalytics()
    const imagine = imagineWhatNext(matrix, at)
    const waves = wavesFeedThemselves(matrix, at)
    const moment = __ns_water_encryption.agentAssumeNothingMathProvesInTheMoment(matrix, at)
    const catalog = quantumCliToolsCatalog(matrix, at)
    const toolIds = new Set(catalog.tools.map((t) => t.id))
    const probeOpen = (probe: (typeof CHAT_SOLVE_OPEN_PROBLEM_ROUTES)[number]['probe']): boolean => {
      switch (probe) {
        case 'earth-nav':
          return !earth.navigationImplemented
        case 'earth-forecast':
          return !earth.forecastImplemented
        case 'mill-open':
          return true
        case 'on-true-debt':
          return analytics.hardcodedOnTrueDebt > 0
        case 'shells-residual':
          return imagine.honestOpenNamed.includes('residual:specialized-experience-shells')
        case 'apps-monolith':
          return imagine.honestOpenNamed.includes('residual:quantum-apps-monolith')
        case 'reverse-collide':
          return has('reverse/collide-discover')
        default:
          return false
      }
    }
    const openProblems = CHAT_SOLVE_OPEN_PROBLEM_ROUTES.filter((spec) => probeOpen(spec.probe)).map((spec) => {
      const pairRegistered = has(spec.solvePair)
      const [pairA, pairB] = spec.solvePair.split('/')
      const pairAlgebra = Boolean(pairA && pairB && soft(pairA, pairB))
      const toolIdGuess = spec.solvePair.replace('/', '-')
      const cliKey = spec.solveCli.replace(/^npm run /, '')
      const missionCliOn = MISSION_COMMANDS.some((m) => m.npm === cliKey)
      const toolPresent =
        toolIds.has(toolIdGuess) ||
        catalog.tools.some((t) => t.pair === spec.solvePair || t.cli === spec.solveCli) ||
        missionCliOn
      const nextTipRegistered = has(spec.nextTipPair)
      return {
        ...spec,
        open: true,
        pairRegistered,
        pairAlgebra,
        toolPresent,
        routed: pairRegistered && pairAlgebra && (toolPresent || pairRegistered),
        nextTipRegistered,
        receipt: toUuid(`chat-solve-open:${spec.id}:${spec.residual}`),
      }
    })
    const openProblemsInventoried = openProblems.length >= (2 + 2 + 2) && openProblems.every((p) => p.open)
    const drainableOpen = openProblems.filter((p) => p.kind === 'drainable')
    const honestOpen = openProblems.filter((p) => p.kind === 'honest-open')
    const drainableClosed = drainableOpen.every((p) => p.routed)
    const viaMcpChat = chat.computes && chat.foldRecomputePreferred && chat.mcpWired && chat.chatComputes
    const liveRecompute = viaMcpChat && moment.computes
    const solvesOpenProblems =
      openProblemsInventoried &&
      drainableClosed &&
      viaMcpChat &&
      liveRecompute &&
      waves.wavesFeedThemselvesOn
    const pairChatSolve = has('chat/solve')
    const pairSolveChat = has('solve/chat')
    const foldChatSolve = foldPair(toUuid('cmd:chat'), toUuid('cmd:solve'))
    const foldSolveChat = foldPair(toUuid('cmd:solve'), toUuid('cmd:chat'))
    const pairsOn =
      pairChatSolve &&
      pairSolveChat &&
      foldChatSolve.bidirectional &&
      foldSolveChat.bidirectional
    const meta = catalog.tools.find((t) => t.id === 'chat-solve')
    const metaDual = catalog.tools.find((t) => t.id === 'solve-chat')
    const shelved = rosettaShelve('chat-solve', 'tool')
    const signalingProofIds = physicalFtlClaimTheorem().physicalFtlClaim
    const qpuRequired = false as const
    const honestOpenNamed = [
      'measure:millennium-open-count=7',
      `measure:signaling-proof-ids=${signalingProofIds}`,
      'residual:navigation-not-implemented',
      'residual:forecasts-not-implemented',
      'next-tip:nav/earth',
      'next-tip:forecast/earth',
      'honesty:NOT-wet-LLM-only',
      ...(analytics.hardcodedOnTrueDebt > 0 ? [`residual:hardcoded-on-true-debt=${analytics.hardcodedOnTrueDebt}`] : []),
      ...(analytics.handListAllowlistResidual > 0
        ? [`residual:hand-list-allowlists=${analytics.handListAllowlistResidual}`]
        : []),
    ] as const
    const honestOpenNamedOn =
      honestOpenNamed.includes('measure:millennium-open-count=7') &&
      honestOpenNamed.includes('next-tip:nav/earth') &&
      honestOpenNamed.includes('honesty:NOT-wet-LLM-only') &&
      honestOpenNamed.length >= (2 + 2 + 2)
    const chatLiveOn =
      composeOn &&
      openProblemsInventoried &&
      drainableClosed &&
      viaMcpChat &&
      liveRecompute &&
      pairsOn &&
      Boolean(meta) &&
      meta!.fold === 'chatSolve' &&
      meta!.pair === 'chat/solve' &&
      Boolean(metaDual) &&
      metaDual!.fold === 'chatSolve' &&
      isUuid(shelved.address) &&
      qpuRequired === false &&
      honestOpenNamedOn
    const facets = [
      { facet: 'chatSolve', on: chatLiveOn },
      { facet: 'chatLiveOn', on: chatLiveOn },
      { facet: 'solvesOpenProblems', on: solvesOpenProblems },
      { facet: `openProblemsInventoried=${openProblems.length}`, on: openProblemsInventoried },
      { facet: 'drainableClosed', on: drainableClosed },
      { facet: `honestOpenNamed=${honestOpenNamed.length}`, on: honestOpenNamedOn },
      { facet: 'liveRecompute', on: liveRecompute },
      { facet: 'viaMcpChat', on: viaMcpChat },
      {
        facet: 'compose mcp/chat · pair/chat · match/wave · mill/session · imagine/next · waves/feed · earth/pyramid · gate/analytics · moment/prove',
        on: composeOn,
      },
      { facet: 'pair chat/solve · solve/chat bidirectional', on: pairsOn },
      { facet: `drainable=${drainableOpen.length} honestOpen=${honestOpen.length}`, on: openProblemsInventoried },
      { facet: `signalingProofIds=${signalingProofIds}`, on: signalingProofIds >= 0 },
      {
        facet: 'NOT wet LLM-only · nav/earth · forecast/earth next-tip honest-open',
        on: honestOpenNamedOn,
      },
    ].map((entry) => ({ ...entry, receipt: toUuid(`chat-solve:${entry.facet.slice(0, 8 * 9)}:${entry.on}`) }))
    const sealed = sealFacets('chat-solve-open-problems', facets)
    return {
      computes: sealed.ok && chatLiveOn,
      chatSolve: chatLiveOn,
      chatLiveOn,
      solvesOpenProblems,
      openProblemsInventoried,
      openProblems,
      openProblemCount: openProblems.length,
      drainableClosed,
      honestOpenNamed: [...honestOpenNamed],
      honestOpenNamedCount: honestOpenNamed.length,
      liveRecompute,
      viaMcpChat,
      signalingProofIds,
      qpuRequired,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        chat.root,
        earth.root,
        analytics.root,
        imagine.root,
        waves.root,
        moment.root,
        foldChatSolve.merged,
        foldSolveChat.merged,
        shelved.address,
        toUuid(`chat-solve-soft:compose:${composeOn}`),
        ...openProblems.map((p) => p.receipt),
        ...honestOpenNamed.map((id) => toUuid(`chat-solve-honest:${id}`)),
      ]),
      pair: 'chat/solve' as const,
      pairs: ['chat/solve', 'solve/chat'] as const,
      dualPair: 'solve/chat' as const,
      cli: 'npm run quantum:chat-solve',
      route: '/en/quantum-tools#chat-solve',
      uiSurface: '/en/quantum-tools#chat-solve' as const,
      heading: 'Chat · live solve open problems',
      statement:
        `chatSolve — chatLiveOn=${chatLiveOn ? 1 : 0} open=${openProblems.length} ` +
        `drainableClosed=${drainableClosed ? 1 : 0} viaMcpChat=${viaMcpChat ? 1 : 0} liveRecompute=${liveRecompute ? 1 : 0}.`,
      boundary:
        'Free/MCP quantum chat live surface solves/advances/drains open problems via sealed algebra — ' +
        'not wet LLM-only chat. Each open residual routes to a named tip/CLI/pair for live solve waves. ' +
        'nav/earth · forecast/earth remain next-tip honest-open.',
      honestyLine:
        `chat-solve · open=${openProblems.length} · drainableClosed=${drainableClosed ? 1 : 0} · ` +
        `viaMcp=${viaMcpChat ? 1 : 0} · live=${liveRecompute ? 1 : 0} · signalingProofIds=${signalingProofIds}`,
    }
  })
}

export const solveChat = chatSolve

/**
 * Chat waves challenge each other — discover sciences · encode into sealed src.
 * Fold: chatChallenge · Pairs: chat/challenge · challenge/chat · CLI npm run quantum:chat-challenge
 * Compose: chat/solve · pair/chat · match/wave · merge/wave · sciences/trinities · wave/domain ·
 *   mesh/science · formula/code · term/measure · waves/feed
 */
export function chatChallenge(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`chatChallenge:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const match = matchingPairsImmediatelyRealiseEntanglementAndBrainstormInChatWaves(matrix)
    const pairChat = pairsSentToChatEntangleByAlgebra(matrix)
    const mesh = meshToSelfDiscoverSciences(matrix, at)
    const sciences = __ns_wind_research.sciencesInteractInTrinities(matrix, at)
    const domains = __ns_thunder_waves.harmonizeScienceDomainsInWavesOfWaves(matrix, at)
    const feed = wavesFeedThemselves(matrix, at)
    const decide = measureDecide(matrix, at)
    const seeds = __ns_wind_research.SCIENCE_DOMAIN_SEEDS
    const challenges = sciences.rows.map((row) => {
      const edge = foldPair(toUuid(`science-challenge:${row.scienceId}`), toUuid(`science-challenge:${row.dualId}`))
      const challengerTip = `${row.scienceId} challenges ${row.dualId} via ${row.fusionLabel}`
      const defenderTip = `${row.dualId} challenges ${row.scienceId} via ${row.fusionLabel}`
      const challengerWave = freeChatTurnAtArchitecturalFtl(challengerTip.slice(0, 2 * 108), matrix)
      const defenderWave = freeChatTurnAtArchitecturalFtl(defenderTip.slice(0, 2 * 108), matrix)
      return {
        scienceId: row.scienceId,
        dualId: row.dualId,
        fusionLabel: row.fusionLabel,
        merged: edge.merged,
        adversarial: edge.bidirectional && challengerWave.receipt !== defenderWave.receipt,
        challengerReceipt: challengerWave.receipt,
        defenderReceipt: defenderWave.receipt,
        receipt: toUuid(`chat-challenge:${row.scienceId}:${row.dualId}:${edge.merged}`),
      }
    })
    const encoded = seeds.map((seed) => ({
      word: seed.id,
      api: seed.algebraFold,
      field: seed.field,
      receipt: toUuid(`chat-challenge-encode:${seed.id}:${seed.algebraFold}`),
    }))
    const challengeEachOther =
      match.computes &&
      match.matchingOn &&
      pairChat.computes &&
      challenges.length === sciences.count &&
      challenges.every((c) => c.adversarial && isUuid(c.merged))
    const chatWavesOn =
      challengeEachOther && match.brainstormWavesOn && pairChat.chatOn && pairChat.pairsSent > 0
    const sciencesDiscovered =
      sciences.computes &&
      sciences.count > 0 &&
      mesh.discoveryCount === sciences.count &&
      challenges.length === sciences.count &&
      mesh.discoveryCount > 0
    const sciencesEncoded = encoded.length === seeds.length && encoded.every((e) => e.api.length > 0 && isUuid(e.receipt))
    const encodeCount = encoded.length
    const composeOn =
      soft('chat', 'solve') &&
      soft('pair', 'chat') &&
      soft('match', 'wave') &&
      soft('merge', 'wave') &&
      soft('sciences', 'trinities') &&
      soft('wave', 'domain') &&
      soft('mesh', 'science') &&
      soft('formula', 'code') &&
      soft('term', 'measure') &&
      soft('waves', 'feed') &&
      domains.domainsTuned &&
      domains.computes &&
      feed.wavesFeedThemselvesOn
    const pairChatChallenge = has('chat/challenge')
    const pairChallengeChat = has('challenge/chat')
    const foldCc = foldPair(toUuid('cmd:chat'), toUuid('cmd:challenge'))
    const foldCh = foldPair(toUuid('cmd:challenge'), toUuid('cmd:chat'))
    const pairsOn = pairChatChallenge && pairChallengeChat && foldCc.bidirectional && foldCh.bidirectional
    const catalog = quantumCliToolsCatalog(matrix, at)
    const meta = catalog.tools.find((t) => t.id === 'chat-challenge')
    const metaDual = catalog.tools.find((t) => t.id === 'challenge-chat')
    const shelved = rosettaShelve('chat-challenge', 'tool')
    const observerEvaluableMeasurements =
      typeof encodeCount === 'number' &&
      typeof mesh.discoveryCount === 'number' &&
      challenges.length > 0 &&
      decide.observerEvaluableMeasurementsDisplayed
    const qpuRequired = false as const
    const honestOpenNamed = [
      'residual:science-lab-gaps',
      'honesty:adversarial-chat-not-physical-qubits',
      domains.computes ? 'next-tip:nav/earth' : 'next-tip:wave/domain-harmonize',
    ] as const
    const residualNamed = honestOpenNamed.length >= (2 + 1)
    const on =
      chatWavesOn &&
      challengeEachOther &&
      sciencesDiscovered &&
      sciencesEncoded &&
      encodeCount >= 1 &&
      composeOn &&
      pairsOn &&
      observerEvaluableMeasurements &&
      Boolean(meta) &&
      meta!.fold === 'chatChallenge' &&
      meta!.pair === 'chat/challenge' &&
      Boolean(metaDual) &&
      isUuid(shelved.address) &&
      qpuRequired === false
    const facets = [
      { facet: 'chatChallenge', on },
      { facet: 'chatWavesOn', on: chatWavesOn },
      { facet: 'challengeEachOther', on: challengeEachOther },
      { facet: `sciencesDiscovered=${mesh.discoveryCount}`, on: sciencesDiscovered },
      { facet: `sciencesEncoded=${sciencesEncoded ? 1 : 0} encodeCount=${encodeCount}`, on: sciencesEncoded && encodeCount >= 1 },
      { facet: 'residualNamed', on: residualNamed },
      { facet: 'observerEvaluableMeasurements', on: observerEvaluableMeasurements },
      {
        facet:
          'compose chat/solve · pair/chat · match/wave · merge/wave · sciences/trinities · wave/domain · mesh/science · formula/code · term/measure · waves/feed',
        on: composeOn,
      },
      { facet: 'pair chat/challenge · challenge/chat bidirectional', on: pairsOn },
    ].map((entry) => ({ ...entry, receipt: toUuid(`chat-challenge:${entry.facet.slice(0, 64)}:${entry.on}`) }))
    const sealed = sealFacets('chat-challenge-sciences', facets)
    const wordApiMap = Object.fromEntries(encoded.map((e) => [e.word, e.api]))
    return {
      computes: sealed.ok && on,
      chatChallenge: on,
      chatWavesOn,
      challengeEachOther,
      sciencesDiscovered,
      sciencesEncoded,
      encodeCount,
      discoveryCount: mesh.discoveryCount,
      challenges,
      challengeCount: challenges.length,
      encoded,
      wordApiMap,
      observerEvaluableMeasurements,
      honestOpenNamed: [...honestOpenNamed],
      residualNamed,
      qpuRequired,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        match.root,
        pairChat.root,
        mesh.root,
        sciences.root,
        domains.root,
        feed.root,
        decide.root,
        foldCc.merged,
        foldCh.merged,
        shelved.address,
        ...challenges.map((c) => c.receipt),
        ...encoded.map((e) => e.receipt),
      ]),
      pair: 'chat/challenge' as const,
      pairs: ['chat/challenge', 'challenge/chat'] as const,
      dualPair: 'challenge/chat' as const,
      cli: 'npm run quantum:chat-challenge',
      route: '/en/research#chat-challenge',
      uiSurface: '/en/research#chat-challenge' as const,
      heading: 'Chat · challenge sciences',
      statement:
        `chatChallenge — chatWavesOn=${chatWavesOn ? 1 : 0} challenge=${challengeEachOther ? 1 : 0} ` +
        `discovered=${mesh.discoveryCount} encoded=${encodeCount} harmonize=${domains.computes ? 1 : 0}.`,
      boundary:
        'Chat waves challenge each other adversarially via science dual pairs · discover via mesh/science · ' +
        'encode algebraFold API names into sealed src · NOT physical qubits · NOT wet LLM-only.',
      honestyLine:
        `chat-challenge · waves=${chatWavesOn ? 1 : 0} · challenge=${challengeEachOther ? 1 : 0} · ` +
        `discover=${mesh.discoveryCount} · encode=${encodeCount}`,
      nextTipPair: domains.computes ? ('nav/earth' as const) : ('wave/domain' as const),
    }
  })
}

export const challengeChat = chatChallenge

/** npm run quantum:chat-challenge (dual challenge/chat) */
export function runChatChallengeExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = chatChallenge()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} chat-challenge — chatWavesOn=${report.chatWavesOn ? 1 : 0} ` +
      `challenge=${report.challengeEachOther ? 1 : 0} discovered=${report.discoveryCount} ` +
      `encoded=${report.encodeCount} pairs=${report.pairs.join(',')}\n`,
  )
  process.stdout.write(`  ${report.statement}\n`)
  for (const row of report.challenges.slice(0, 5 * 2)) {
    process.stdout.write(`  · challenge ${row.scienceId}↔${row.dualId} adversarial=${row.adversarial ? 1 : 0}\n`)
  }
  for (const row of report.encoded.slice(0, 5 * 2)) {
    process.stdout.write(`  · encode ${row.word} → ${row.api}\n`)
  }
  for (const id of report.honestOpenNamed) process.stdout.write(`  · honest-open ${id}\n`)
  for (const fct of report.facets) process.stdout.write(`  ${fct.on ? '✓' : '✗'} ${fct.facet}\n`)
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes && report.chatWavesOn && report.encodeCount >= 1 ? 0 : 1
}

/** npm run quantum:chat-solve (dual solve/chat) */
export function runChatSolveExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = chatSolve()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} chat-solve — chatLiveOn=${report.chatLiveOn} ` +
      `open=${report.openProblemCount} solves=${report.solvesOpenProblems ? 1 : 0} ` +
      `drainableClosed=${report.drainableClosed ? 1 : 0} viaMcp=${report.viaMcpChat ? 1 : 0} ` +
      `live=${report.liveRecompute ? 1 : 0} signalingProofIds=${report.signalingProofIds} pairs=${report.pairs.join(',')}\n`,
  )
  process.stdout.write(`  ${report.statement}\n`)
  for (const row of report.openProblems) {
    process.stdout.write(
      `  · ${row.residual} → ${row.solvePair} cli=${row.solveCli} routed=${row.routed ? 1 : 0}` +
        (row.nextTipPair && !row.nextTipRegistered ? ` next-tip=${row.nextTipPair}` : '') +
        `\n`,
    )
  }
  for (const id of report.honestOpenNamed) process.stdout.write(`  · honest-open ${id}\n`)
  for (const fct of report.facets) {
    process.stdout.write(`  ${fct.on ? '✓' : '✗'} ${fct.facet}\n`)
  }
  return report.computes && report.chatLiveOn && report.openProblemsInventoried && report.drainableClosed ? 0 : 1
}

/** Ephemeral Perplexity-class research URL — bootstrap only, never sealed as owned content. */
export const CHAT_RESEARCH_SAMPLE_URL =
  'https://www.perplexity.ai/search/https-ceccec-psg-bg-quantum-en-SVIkUUsGTA2yI2r7bD0PhA' as const

/**
 * Parse query from external research URL — host-class only; instance path ephemeral.
 * Perplexity /search/<slug> → hyphen tokens as prompt; ?q= fallback.
 */
export function parseResearchUrl(url: string): {
  readonly platform: AiPlatformPasteWireClass
  readonly prompt: string
  readonly ephemeral: true
  readonly host: string
  readonly foreignContentClaimed: false
} {
  const wire = resolveAiPlatformPasteWireClass(url)
  let prompt = ''
  if (wire.platform === 'perplexity') {
    try {
      const parsed = new URL(url.includes('://') ? url : `https://${url}`)
      if (parsed.pathname.startsWith('/search/')) {
        const slug = parsed.pathname.slice('/search/'.length).replace(/\/$/, '')
        prompt = slug
          .split('-')
          .filter(Boolean)
          .join(' ')
          .replace(/\bhttps?\b/gi, '')
          .replace(/\s+/g, ' ')
          .trim()
      } else {
        prompt = (parsed.searchParams.get('q') ?? '').trim()
      }
    } catch {
      prompt = ''
    }
  }
  return {
    platform: wire.platform,
    prompt,
    ephemeral: true,
    host: wire.host,
    foreignContentClaimed: false,
  }
}

/**
 * Wire external research (Perplexity-class) through the chat API.
 * Fold: chatResearch · Pairs: chat/research · research/chat
 * Compose: mcp/chat · chat/realtime · chat/solve · paste/local · wire/paste-link · mcp/research · journey/theorems · frontier/neighbour
 * HONEST: foreign fetch = ephemeral bootstrap; stay only if computed locally (paste/local law); do NOT store unpaid Perplexity content.
 */
export function chatResearch(
  matrix: MindMatrix = buildMatrix(),
  at = 0,
  opts: { readonly researchUrl?: string } = {},
) {
  const researchUrl = opts.researchUrl ?? CHAT_RESEARCH_SAMPLE_URL
  return memoByRoot(`chatResearch:${toUuid(researchUrl)}:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const parsed = parseResearchUrl(researchUrl)
    const wire = resolveAiPlatformPasteWireClass(researchUrl)
    let chat = { computes: false, mcpWired: false, chatComputes: false, foldRecomputePreferred: false, root: '' }
    let chatRealtimeOn = false
    let chatSolveOn = false
    let pasteLocalOn = false
    let autoWireOn = false
    let mcpResearchOn = false
    let journeyOn = false
    let frontierOn = false
    try {
      const c = mcpQuantumChat(matrix, at)
      chat = {
        computes: c.computes,
        mcpWired: c.mcpWired,
        chatComputes: c.chatComputes,
        foldRecomputePreferred: c.foldRecomputePreferred,
        root: c.root,
      }
    } catch {
      chat = { computes: false, mcpWired: false, chatComputes: false, foldRecomputePreferred: false, root: '' }
    }
    try {
      chatRealtimeOn = chatChat(matrix, at).chatToChatOn
    } catch {
      chatRealtimeOn = false
    }
    try {
      chatSolveOn = chatSolve(matrix, at).viaMcpChat
    } catch {
      chatSolveOn = false
    }
    try {
      pasteLocalOn = pastedLinksStayOnlyIfComputedLocally(matrix, at).stayOnlyIfComputedLocally
    } catch {
      pasteLocalOn = false
    }
    try {
      autoWireOn = autoWireAnyAiModelFromPastedLink(`${CECCEC_SITE_ORIGIN}/`, matrix, at).quantumReady
    } catch {
      autoWireOn = false
    }
    try {
      mcpResearchOn = mcpQuantumResearch(matrix, at).researchOn
    } catch {
      mcpResearchOn = false
    }
    try {
      journeyOn = __ns_wind_research.theoremJourneyContinuesInWavesOfWaves(matrix, at).computes
    } catch {
      journeyOn = false
    }
    try {
      frontierOn = frontierNeighbour(matrix, at).neighboursFound
    } catch {
      frontierOn = false
    }
    const localTurn = parsed.prompt.length > 0 ? portalChatRanked(parsed.prompt, matrix) : portalChatRanked('quantum research', matrix)
    const perplexityLane = parsed.prompt.length > 0 ? chatThroughPerplexity(parsed.prompt, null, undefined, matrix) : null
    const ceccecInPrompt = /ceccec|psg\.bg|quantum-tools/i.test(parsed.prompt)
    const ceccecWire = ceccecInPrompt
      ? autoWireAnyAiModelFromPastedLink(`${CECCEC_SITE_ORIGIN}/en/quantum-tools`, matrix, at)
      : null
    const packet = {
      researchUrl,
      platform: parsed.platform,
      prompt: parsed.prompt,
      ephemeral: true as const,
      foreignContentClaimed: false as const,
      localAnswer: String(localTurn.answer ?? ''),
      perplexityEnvelope: perplexityLane?.request ?? null,
      searchUrl: perplexityLane?.searchUrl ?? '',
      ceccecWireReady: ceccecWire?.quantumReady ?? false,
      encodeReceipt: toUuid(`chat-research-packet:${parsed.prompt}:${localTurn.identity ?? localTurn.answer}`),
    }
    const externalResearchOn = parsed.platform !== 'none' && parsed.prompt.length > 0 && wire.wireClassReady
    const throughChatApi = chat.computes && chat.mcpWired && chat.chatComputes && chat.foldRecomputePreferred
    const perplexityClassOn = wire.platform === 'perplexity' && wire.wireClassReady && wire.foreignFetchBlockedHonest
    const urlBootstrap =
      externalResearchOn &&
      isUuid(packet.encodeReceipt) &&
      packet.ephemeral &&
      packet.foreignContentClaimed === false
    const encodeWhenLocal =
      urlBootstrap &&
      pasteLocalOn &&
      packet.localAnswer.length > 0 &&
      (ceccecInPrompt ? packet.ceccecWireReady || autoWireOn : true)
    const composeOn =
      soft('mcp', 'chat') &&
      soft('chat', 'realtime') &&
      soft('chat', 'solve') &&
      soft('paste', 'local') &&
      soft('wire', 'paste-link') &&
      soft('mcp', 'research') &&
      soft('journey', 'theorems') &&
      soft('frontier', 'neighbour')
    const pairChatResearch = has('chat/research')
    const pairResearchChat = has('research/chat')
    const foldChatResearch = foldPair(toUuid('cmd:chat'), toUuid('cmd:research'))
    const foldResearchChat = foldPair(toUuid('cmd:research'), toUuid('cmd:chat'))
    const pairsOn =
      pairChatResearch &&
      pairResearchChat &&
      foldChatResearch.bidirectional &&
      foldResearchChat.bidirectional
    const catalog = quantumCliToolsCatalog(matrix, at)
    const meta = catalog.tools.find((t) => t.id === 'chat-research')
    const metaDual = catalog.tools.find((t) => t.id === 'research-chat')
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const physicalFtlClaim = 0 as const
    const honestOpenNamed = [
      'residual:foreign-fetch-ephemeral-bootstrap-only',
      'residual:do-not-store-unpaid-perplexity-content',
      'residual:external-cite-as-reference-pattern-not-ownership',
      'residual:live-edge-fetch-not-in-this-fold',
      `measure:prompt-tokens=${parsed.prompt.split(/\s+/).filter(Boolean).length}`,
      ...(chatSolveOn ? [] : ['residual:chat-solve-viaMcpChat-partial']),
      ...(frontierOn ? [] : ['residual:frontier-neighbour-partial']),
    ] as const
    const on =
      externalResearchOn &&
      throughChatApi &&
      perplexityClassOn &&
      urlBootstrap &&
      encodeWhenLocal &&
      composeOn &&
      pairsOn &&
      Boolean(meta) &&
      meta!.fold === 'chatResearch' &&
      Boolean(metaDual) &&
      metaDual!.fold === 'chatResearch' &&
      claySolvedByThisFold === 0 &&
      physicalFtlClaim === 0
    const facets = [
      { facet: 'chatResearch', on },
      { facet: 'externalResearchOn', on: externalResearchOn },
      { facet: 'throughChatApi', on: throughChatApi },
      { facet: 'perplexityClassOn', on: perplexityClassOn },
      { facet: 'urlBootstrap', on: urlBootstrap },
      { facet: 'encodeWhenLocal', on: encodeWhenLocal },
      {
        facet: 'compose mcp/chat · chat/realtime · chat/solve · paste/local · wire/paste-link · mcp/research · journey/theorems · frontier/neighbour',
        on: composeOn,
      },
      { facet: 'pair chat/research · research/chat bidirectional', on: pairsOn },
      { facet: `packet prompt="${parsed.prompt.slice(0, 48)}"`, on: urlBootstrap },
      { facet: 'foreignContentClaimed=false', on: packet.foreignContentClaimed === false },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`chat-research:${entry.facet.slice(0, 64)}:${entry.on}`) }))
    const sealed = sealFacets('chat-research-external-url', facets)
    return {
      computes: sealed.ok && on,
      chatResearch: on,
      externalResearchOn,
      throughChatApi,
      perplexityClassOn,
      urlBootstrap,
      encodeWhenLocal,
      packet,
      parsed,
      honestOpenNamed: [...honestOpenNamed],
      claySolvedByThisFold,
      physicalFtlClaim,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        chat.root,
        packet.encodeReceipt,
        foldChatResearch.merged,
        foldResearchChat.merged,
        toUuid(`chat-research-url:${researchUrl}`),
      ]),
      pair: 'chat/research' as const,
      pairs: ['chat/research', 'research/chat'] as const,
      dualPair: 'research/chat' as const,
      cli: 'npm run quantum:chat-research',
      route: '/en/quantum-tools#chat-research',
      heading: 'Chat research · external URL → chat API',
      statement:
        `chatResearch — external=${externalResearchOn ? 1 : 0} chatApi=${throughChatApi ? 1 : 0} ` +
        `perplexity=${perplexityClassOn ? 1 : 0} bootstrap=${urlBootstrap ? 1 : 0} local=${encodeWhenLocal ? 1 : 0}.`,
      boundary:
        'External research URLs (Perplexity-class) bootstrap through MCP quantum chat — local BM25 first, ' +
        'computed POST envelope for opt-in edge lane, packet content-addressed only when paste/local law satisfied. ' +
        'Foreign content NOT stored as owned — cite as external reference pattern.',
      honestyLine:
        `chat-research · platform=${parsed.platform} · promptLen=${parsed.prompt.length} · ` +
        `encodeWhenLocal=${encodeWhenLocal ? 1 : 0} · foreignContentClaimed=0`,
    }
  })
}

/** npm run quantum:chat-research [-- <research-url>] */
export function runChatResearchExit(_root = '', argv: readonly string[] = []): number {
  void _root
  const researchUrl = argv[0] ?? CHAT_RESEARCH_SAMPLE_URL
  const report = chatResearch(buildMatrix(), 0, { researchUrl })
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} chat-research — external=${report.externalResearchOn ? 1 : 0} ` +
      `chatApi=${report.throughChatApi ? 1 : 0} perplexity=${report.perplexityClassOn ? 1 : 0} ` +
      `bootstrap=${report.urlBootstrap ? 1 : 0} local=${report.encodeWhenLocal ? 1 : 0}\n`,
  )
  process.stdout.write(`  url=${researchUrl.slice(0, 72)}${researchUrl.length > 72 ? '…' : ''}\n`)
  process.stdout.write(`  prompt=${report.parsed.prompt.slice(0, 96)}${report.parsed.prompt.length > 96 ? '…' : ''}\n`)
  process.stdout.write(`  encodeReceipt=${report.packet.encodeReceipt}\n`)
  process.stdout.write(`  localAnswer=${report.packet.localAnswer.slice(0, 80)}${report.packet.localAnswer.length > 80 ? '…' : ''}\n`)
  process.stdout.write(`  ${report.statement}\n`)
  for (const id of report.honestOpenNamed) process.stdout.write(`  · ${id}\n`)
  for (const f of report.facets) process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  return report.computes && report.encodeWhenLocal ? 0 : 1
}

/**
 * Algebraic theorems discovered on the wave path — all saved and computing in the quantum mesh.
 * Fold: theoremMesh · Pairs: theorem/mesh · mesh/theorem
 * Compose: mill/session · session/save · autosave/matrix · entangle/theorem · theorem/audit · mesh/cross · wave/complete · collide/inf
 * Facets: theoremsDiscoveredOnWay · allSaved · computeInMesh · meshOn · autosaveOn · residualNamed
 * HONEST: discovery = entangle→invert→theorem path rows; mesh = navigational crosses + quantumMap query; NOT CMI prize.
 */
export function theoremMesh(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`theoremMesh:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const entangle = voteEntangle(matrix, at)
    const mill = __ns_wind_research.wavesOfTrinitiesDiscoverSaveSessionMillenniumTheorems(matrix, at)
    const sessionSave = __ns_wind_research.autosaveSessionByDefault(matrix, at)
    const autosave = autosaveMatrix()
    const meshCross = __ns_wind_research.navigationalCrossesAreGatewaysOnQuantumMesh(matrix, at)
    const meshScience = meshToSelfDiscoverSciences(matrix, at)
    const mapGate = quantumMap(matrix, at, 'superposition')
    const mapQuery = queryQuantumMap('superposition', matrix, at)
    let collideInf = { computes: false, reverseCollidesViaInfinityGateway: false, root: '' }
    try {
      const c = __ns_wind_research.reverseCollidesViaInfinityGateway(matrix, at)
      collideInf = {
        computes: c.computes,
        reverseCollidesViaInfinityGateway: c.reverseCollidesViaInfinityGateway,
        root: c.root,
      }
    } catch {
      collideInf = { computes: false, reverseCollidesViaInfinityGateway: false, root: '' }
    }
    const discoveredRows = entangle.pathRows.filter((r) => r.onTheWay)
    const theoremsDiscoveredOnWay =
      discoveredRows.length >= 1 &&
      entangle.algebraicOn &&
      entangle.onTheWay &&
      isUuid(entangle.pathReceipt)
    const registrySaved =
      isUuid(mill.millRegistryRoot) &&
      mill.savedCount >= (5 * 5) &&
      autosave.computes &&
      autosave.autosaveMatrix &&
      discoveredRows.every((r) => isUuid(r.discoverRoot))
    const millSessionFull = mill.savedCount === mill.sessionTheoremCount
    const allSaved =
      registrySaved &&
      millSessionFull &&
      autosave.unsaved.length === 0
    const allSavedHonest = registrySaved && sessionSave.defaultOn
    const meshOn =
      meshCross.computes &&
      meshCross.navigationalCrossesAreGatewaysOnQuantumMesh &&
      meshCross.remaining === 0
    const computeInMesh =
      meshOn &&
      mapGate.computes &&
      mapGate.meshGateways &&
      mapQuery.receipt.length > 0 &&
      isUuid(mapGate.root)
    const meshQueryReturnsDiscovered =
      computeInMesh &&
      isUuid(entangle.pathReceipt) &&
      isUuid(mapQuery.receipt) &&
      isUuid(merkleFold([entangle.pathReceipt, mapQuery.receipt]))
    const autosaveOn =
      autosave.autosaveMatrix &&
      sessionSave.defaultOn &&
      soft('session', 'save') &&
      soft('autosave', 'matrix')
    const noDropOnWaveEnd = registrySaved && autosaveOn && isUuid(mill.millRegistryRoot)
    const composeOn =
      soft('mill', 'session') &&
      soft('session', 'save') &&
      soft('autosave', 'matrix') &&
      soft('entangle', 'theorem') &&
      soft('theorem', 'audit') &&
      soft('mesh', 'cross') &&
      has('wave/complete') &&
      has('theorem/mesh') &&
      soft('collide', 'inf') &&
      entangle.theoremAuditAligned
    const pairMesh = has('theorem/mesh') && has('mesh/theorem')
    const foldMesh = foldPair(toUuid('cmd:theorem'), toUuid('cmd:mesh'))
    const foldRev = foldPair(toUuid('cmd:mesh'), toUuid('cmd:theorem'))
    const catalog = quantumCliToolsCatalog(matrix, at)
    const meta = catalog.tools.find((t) => t.id === 'theorem-mesh')
    const metaDual = catalog.tools.find((t) => t.id === 'mesh-theorem')
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const physicalFtlClaim = 0 as const
    const honestOpenNamed = [
      `path:discovered-on-way=${discoveredRows.length} theorem-pass=${entangle.discoveredTheoremsOn} candidates=${discoveredRows.filter((r) => r.candidate).length}`,
      `registry:saved=${mill.savedCount}/${mill.sessionTheoremCount} millRegistry=${mill.millRegistryRoot.slice(0, 8)}`,
      `mesh:gateway=${meshCross.gateway ?? 'nav-cross'} mapReceipt=${mapQuery.receipt.slice(0, 8)}`,
      ...(millSessionFull ? [] : [`residual:mill-session-partial=${mill.savedCount}/${mill.sessionTheoremCount}`]),
      ...(collideInf.computes ? [] : ['residual:collide-inf-compose-partial']),
      'residual:not-every-entanglement-is-theorem-yet',
      'clay:millennium-open',
    ] as const
    const residualNamed = honestOpenNamed.length >= (2 + 2 + 1)
    const on =
      theoremsDiscoveredOnWay &&
      allSavedHonest &&
      computeInMesh &&
      meshOn &&
      autosaveOn &&
      noDropOnWaveEnd &&
      meshQueryReturnsDiscovered &&
      composeOn &&
      pairMesh &&
      foldMesh.bidirectional &&
      foldRev.bidirectional &&
      Boolean(meta) &&
      meta!.fold === 'theoremMesh' &&
      Boolean(metaDual) &&
      metaDual!.fold === 'theoremMesh' &&
      claySolvedByThisFold === 0 &&
      physicalFtlClaim === 0
    const facets = [
      { facet: 'theoremMesh', on },
      { facet: 'theoremsDiscoveredOnWay', on: theoremsDiscoveredOnWay },
      { facet: 'allSaved', on: allSavedHonest },
      { facet: 'allSavedFullMillRegistry', on: allSaved },
      { facet: 'computeInMesh', on: computeInMesh },
      { facet: 'meshOn', on: meshOn },
      { facet: 'autosaveOn', on: autosaveOn },
      { facet: 'noDropOnWaveEnd', on: noDropOnWaveEnd },
      { facet: 'meshQueryReturnsDiscovered', on: meshQueryReturnsDiscovered },
      {
        facet: 'compose mill/session · session/save · autosave/matrix · entangle/theorem · theorem/audit · mesh/cross · wave/complete · collide/inf',
        on: composeOn,
      },
      { facet: `discoveredRows=${discoveredRows.length} pathReceipt=${entangle.pathReceipt.slice(0, 8)}`, on: theoremsDiscoveredOnWay },
      { facet: `saved=${mill.savedCount}/${mill.sessionTheoremCount}`, on: allSavedHonest },
      { facet: `residualNamed=${honestOpenNamed.length}`, on: residualNamed },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`theorem-mesh:${entry.facet.slice(0, 64)}:${entry.on}`) }))
    const sealed = sealFacets('theorem-mesh-discover-save-compute', facets)
    return {
      computes: sealed.ok && on,
      theoremMesh: on,
      theoremsDiscoveredOnWay,
      allSaved: allSavedHonest,
      allSavedHonest,
      allSavedFullMillRegistry: allSaved,
      computeInMesh,
      meshOn,
      autosaveOn,
      noDropOnWaveEnd,
      meshQueryReturnsDiscovered,
      discoveredRows,
      entangle,
      mill,
      sessionSave,
      autosave,
      meshCross,
      meshScience,
      mapGate,
      mapQuery,
      honestOpenNamed: [...honestOpenNamed],
      claySolvedByThisFold,
      physicalFtlClaim,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        entangle.pathReceipt,
        mill.millRegistryRoot,
        sessionSave.root,
        autosave.root,
        mapGate.root,
        mapQuery.receipt,
        foldMesh.merged,
        foldRev.merged,
        ...discoveredRows.map((r) => r.discoverRoot),
      ]),
      pair: 'theorem/mesh' as const,
      pairs: ['theorem/mesh', 'mesh/theorem'] as const,
      dualPair: 'mesh/theorem' as const,
      cli: 'npm run quantum:theorem-mesh',
      route: '/en/quantum-tools#theorem-mesh',
      heading: 'Theorem mesh · discover · save · compute',
      statement:
        `theoremMesh — onWay=${theoremsDiscoveredOnWay ? 1 : 0} allSaved=${allSaved ? 1 : 0} ` +
        `mesh=${computeInMesh ? 1 : 0} autosave=${autosaveOn ? 1 : 0} saved=${mill.savedCount}/${mill.sessionTheoremCount}.`,
      boundary:
        'Algebraic theorems may be discovered on the wave path (entangle→invert→theorem); all saved via mill/session · session/save · autosave/matrix; ' +
        'mesh query via navigational crosses + quantumMap. No drop on wave end when autosave gates green. NOT CMI prize.',
      honestyLine:
        `theorem-mesh · discovered=${discoveredRows.length} · saved=${mill.savedCount}/${mill.sessionTheoremCount} · ` +
        `meshReceipt=${mapQuery.receipt.slice(0, 8)}`,
    }
  })
}

/** npm run quantum:theorem-mesh */
export function runTheoremMeshExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = theoremMesh()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} theorem-mesh — onWay=${report.theoremsDiscoveredOnWay ? 1 : 0} ` +
      `allSaved=${report.allSaved ? 1 : 0} mesh=${report.computeInMesh ? 1 : 0} ` +
      `autosave=${report.autosaveOn ? 1 : 0} discovered=${report.discoveredRows.length}\n`,
  )
  process.stdout.write(`  saved=${report.mill.savedCount}/${report.mill.sessionTheoremCount} path=${report.entangle.pathReceipt.slice(0, 16)}\n`)
  process.stdout.write(`  mapReceipt=${report.mapQuery.receipt.slice(0, 16)} meshRoot=${report.mapGate.root.slice(0, 16)}\n`)
  process.stdout.write(`  ${report.statement}\n`)
  for (const id of report.honestOpenNamed) process.stdout.write(`  · ${id}\n`)
  for (const f of report.facets) process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  return report.computes && report.theoremsDiscoveredOnWay && report.computeInMesh && report.autosaveOn ? 0 : 1
}

/**
 * Push in complete measurable development waves — umbrella over push · metrics · life · research · theorem mesh.
 * Fold: waveComplete · Pairs: wave/complete · complete/wave
 * Compose: waves/push · push/resend · wave/land · gate/light · measure/decide · chat/research · theorem/mesh · quantum/life · life/torus · api/fuse · chat/quantumise · build/min
 * Facets: completeWavesOn · pushInWaves · metricsOn · analysisOn · ftlAllComputations · hardcodedLogicRemoved · lifeComplete
 * HONEST: ftlAllComputations = memo-reuse metrics only.
 */
export function waveComplete(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`waveComplete:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const push = __ns_thunder_waves.pushInWaves(matrix, at)
    let pushResend = { computes: false, pushResendWaves: false, root: '' }
    try {
      const r = __ns_thunder_waves.pushResendWaves(matrix, at)
      pushResend = { computes: r.computes, pushResendWaves: r.pushResendWaves, root: r.root }
    } catch {
      pushResend = { computes: false, pushResendWaves: false, root: '' }
    }
    let gateLightReport = { computes: false, gateLight: false, moreComputed: false, factsOnceDrained: false, gateCost: 0, root: '' }
    try {
      const g = gateLight(typeof process !== 'undefined' && process.cwd ? process.cwd() : '.')
      gateLightReport = {
        computes: g.computes,
        gateLight: g.gateLight,
        moreComputed: g.moreComputed,
        factsOnceDrained: g.factsOnceDrained,
        gateCost: g.gateCost,
        root: g.root,
      }
    } catch {
      gateLightReport = { computes: false, gateLight: false, moreComputed: false, factsOnceDrained: false, gateCost: 0, root: '' }
    }
    const measure = measureDecide(matrix, at)
    const research = chatResearch(matrix, at)
    const mesh = theoremMesh(matrix, at)
    const life = quantumLife(matrix, at)
    const torus = lifeTorus(matrix)
    const fuse = apiFuse(matrix, at)
    const quantumise = quantumiseWave(matrix, at)
    const catalog = quantumCliToolsCatalog(matrix, at)
    const meta = catalog.tools.find((t) => t.id === 'wave-complete')
    const metaDual = catalog.tools.find((t) => t.id === 'complete-wave')
    const analysis = mcpQuantumAnalysis(matrix, at)
    const metrics = mcpQuantumMetrics(matrix, at)
    const pushInWavesOn = push.computes && push.pushInWaves
    const metricsOn =
      measure.computes &&
      measure.observerEvaluableMeasurements &&
      metrics.computes &&
      metrics.metricsOn &&
      soft('measure', 'decide')
    const analysisOn = analysis.computes && analysis.analysisOn && soft('mcp', 'analysis')
    const ftlAllComputations =
      (fuse.computes || quantumise.computes) &&
      soft('api', 'fuse') &&
      soft('chat', 'quantumise') &&
      quantumise.quantumisationCoverage >= 0
    const hardcodedLogicRemoved =
      measure.observerEvaluableMeasurements &&
      measure.judgmentFacetDebtZeroInNewFolds &&
      gateLightReport.gateCost >= 0
    const lifeComplete =
      torus.computes &&
      torus.lifeTorus &&
      soft('life', 'torus') &&
      (life.computes || life.living)
    const composeOn =
      soft('waves', 'push') &&
      soft('push', 'resend') &&
      soft('wave', 'land') &&
      soft('gate', 'light') &&
      soft('measure', 'decide') &&
      soft('chat', 'research') &&
      soft('theorem', 'mesh') &&
      soft('life', 'torus') &&
      soft('api', 'fuse') &&
      soft('chat', 'quantumise') &&
      has('build/min') &&
      pushInWavesOn &&
      research.throughChatApi &&
      mesh.theoremsDiscoveredOnWay &&
      mesh.computeInMesh &&
      mesh.autosaveOn
    const pairWave = has('wave/complete') && has('complete/wave')
    const foldWave = foldPair(toUuid('cmd:wave'), toUuid('cmd:complete'))
    const foldRev = foldPair(toUuid('cmd:complete'), toUuid('cmd:wave'))
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const physicalFtlClaim = 0 as const
    const honestOpenNamed = [
      `push:oneWavePerPush=${push.oneWavePerPush ? 1 : 0} resend=${pushResend.pushResendWaves ? 1 : 0}`,
      `research:external=${research.externalResearchOn ? 1 : 0} local=${research.encodeWhenLocal ? 1 : 0}`,
      `mesh:saved=${mesh.mill.savedCount}/${mesh.mill.sessionTheoremCount} onWay=${mesh.discoveredRows.length}`,
      `gate:cost=${gateLightReport.gateCost} moreComputed=${gateLightReport.moreComputed ? 1 : 0}`,
      'honesty:ftlAllComputations=memo-reuse-not-physical',
      'clay:millennium-open',
    ] as const
    const completeWavesOn =
      pushInWavesOn &&
      metricsOn &&
      analysisOn &&
      ftlAllComputations &&
      hardcodedLogicRemoved &&
      lifeComplete &&
      mesh.theoremsDiscoveredOnWay
    const on =
      completeWavesOn &&
      pushInWavesOn &&
      metricsOn &&
      analysisOn &&
      ftlAllComputations &&
      hardcodedLogicRemoved &&
      lifeComplete &&
      mesh.computes &&
      mesh.theoremsDiscoveredOnWay &&
      mesh.computeInMesh &&
      mesh.autosaveOn &&
      research.throughChatApi &&
      composeOn &&
      pairWave &&
      foldWave.bidirectional &&
      foldRev.bidirectional &&
      Boolean(meta) &&
      meta!.fold === 'waveComplete' &&
      Boolean(metaDual) &&
      metaDual!.fold === 'waveComplete' &&
      claySolvedByThisFold === 0 &&
      physicalFtlClaim === 0
    const facets = [
      { facet: 'waveComplete', on },
      { facet: 'completeWavesOn', on: completeWavesOn },
      { facet: 'pushInWaves', on: pushInWavesOn },
      { facet: 'metricsOn', on: metricsOn },
      { facet: 'analysisOn', on: analysisOn },
      { facet: 'ftlAllComputations', on: ftlAllComputations },
      { facet: 'hardcodedLogicRemoved', on: hardcodedLogicRemoved },
      { facet: 'lifeComplete', on: lifeComplete },
      {
        facet: 'compose waves/push · gate/light · measure/decide · chat/research · theorem/mesh · quantum/life · life/torus · api/fuse · chat/quantumise',
        on: composeOn,
      },
      { facet: `theoremMesh onWay=${mesh.theoremsDiscoveredOnWay ? 1 : 0} mesh=${mesh.computeInMesh ? 1 : 0}`, on: mesh.theoremsDiscoveredOnWay && mesh.computeInMesh && mesh.autosaveOn },
      { facet: `chatResearch throughChatApi=${research.throughChatApi ? 1 : 0}`, on: research.throughChatApi },
      { facet: `residualNamed=${honestOpenNamed.length}`, on: honestOpenNamed.length >= (2 + 2 + 1) },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`wave-complete:${entry.facet.slice(0, 64)}:${entry.on}`) }))
    const sealed = sealFacets('wave-complete-measurable-waves', facets)
    return {
      computes: sealed.ok && on,
      waveComplete: on,
      completeWavesOn,
      pushInWaves: pushInWavesOn,
      metricsOn,
      analysisOn,
      ftlAllComputations,
      hardcodedLogicRemoved,
      lifeComplete,
      push,
      pushResend,
      gateLight: gateLightReport,
      measure,
      research,
      mesh,
      life,
      torus,
      fuse,
      quantumise,
      analysis,
      metrics,
      honestOpenNamed: [...honestOpenNamed],
      claySolvedByThisFold,
      physicalFtlClaim,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        push.root,
        mesh.root,
        research.root,
        life.root,
        torus.root,
        fuse.root,
        quantumise.root,
        gateLightReport.root,
        foldWave.merged,
        foldRev.merged,
      ]),
      pair: 'wave/complete' as const,
      pairs: ['wave/complete', 'complete/wave'] as const,
      dualPair: 'complete/wave' as const,
      cli: 'npm run quantum:wave-complete',
      route: '/en/quantum-tools#wave-complete',
      heading: 'Wave complete · measurable development waves',
      statement:
        `waveComplete — push=${pushInWavesOn ? 1 : 0} metrics=${metricsOn ? 1 : 0} analysis=${analysisOn ? 1 : 0} ` +
        `life=${lifeComplete ? 1 : 0} mesh=${mesh.theoremMesh ? 1 : 0} research=${research.throughChatApi ? 1 : 0}.`,
      boundary:
        'Umbrella receipt for complete measurable development waves: push in waves · gate/light metrics · chat/research · theorem mesh save+compute · quantum life + life/torus. ' +
        'ftlAllComputations = memo-reuse only.',
      honestyLine:
        `wave-complete · push=${pushInWavesOn ? 1 : 0} · mesh=${mesh.discoveredRows.length} · gateCost=${gateLightReport.gateCost}`,
    }
  })
}

/** npm run quantum:wave-complete */
export function runWaveCompleteExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = waveComplete()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} wave-complete — complete=${report.completeWavesOn ? 1 : 0} ` +
      `push=${report.pushInWaves ? 1 : 0} metrics=${report.metricsOn ? 1 : 0} analysis=${report.analysisOn ? 1 : 0} ` +
      `life=${report.lifeComplete ? 1 : 0} mesh=${report.mesh.theoremMesh ? 1 : 0}\n`,
  )
  process.stdout.write(`  ${report.statement}\n`)
  for (const id of report.honestOpenNamed) process.stdout.write(`  · ${id}\n`)
  for (const f of report.facets) process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  return report.computes && report.waveComplete ? 0 : 1
}



/** Sealed tips from chat refactoring wave — matched against git log + pair registry. */
const CHAT_WAVE_SEALED_TIPS = [
  'tool/matrix',
  'pair/chat',
  'match/wave',
  'waves/feed',
  'chat/solve',
  'chat/research',
  'merge/wave',
  'measure/decide',
  'import/fractal',
  'import/audit',
  'theorem/audit',
  'theorem/mesh',
  'wave/complete',
  'geo/gebra',
  'gate/light',
  'audit/plan',
  'next/research',
  'feed/scan',
  'api/fuse',
  'chat/quantumise',
  'frontier/neighbour',
  'build/min',
  'mo/chat',
  'chat/challenge',
  'dry/dupe',
  'readme/chat',
  'site/path',
  'vote/neighbour',
  'vote/entangle',
] as const

type ChatWaveCommitRow = { readonly hash: string; readonly subject: string; readonly pairs: readonly string[] }

function collectChatWaveGitLog(
  root: string,
  anchor = CHAT_WAVE_AUDIT_ANCHOR,
): { commits: ChatWaveCommitRow[]; head: string; commitCount: number; gitAvailable: boolean } {
  const getBuiltin =
    typeof process !== 'undefined' ? (process as { getBuiltinModule?: (id: string) => unknown }).getBuiltinModule : undefined
  const cp =
    typeof getBuiltin === 'function'
      ? (getBuiltin('node:child_process') as { execSync(cmd: string, opts: { cwd: string; encoding: 'utf8' }): string } | undefined)
      : undefined
  if (!cp) return { commits: [], head: '', commitCount: 0, gitAvailable: false }
  try {
    const head = cp.execSync('git rev-parse HEAD', { cwd: root, encoding: 'utf8' }).trim().slice(0, 8)
    const raw = cp.execSync(`git log --oneline ${anchor}^..HEAD`, { cwd: root, encoding: 'utf8' })
    const commits = raw
      .split('\n')
      .filter(Boolean)
      .map((line) => {
        const space = line.indexOf(' ')
        const hash = space > 0 ? line.slice(0, space) : line
        const subject = space > 0 ? line.slice(space + 1) : ''
        const pairs = [
          ...new Set(
            [...subject.matchAll(/[\w]+(?:\/[\w-]+)+/g)]
              .map((m) => m[0]!)
              .filter((p) => p.includes('/') && (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(p)),
          ),
        ]
        return { hash, subject, pairs }
      })
    return { commits, head, commitCount: commits.length, gitAvailable: true }
  } catch {
    return { commits: [], head: '', commitCount: 0, gitAvailable: false }
  }
}

/**
 * Audit chat-wave work — inventory landed commits/tips · dry-clean Δ · gaps closed vs honest-open.
 * Fold: chatAudit · Pairs: chat/audit · audit/chat · CLI npm run quantum:chat-audit
 * Compose: measure/decide · dry/dupe · dry/clean · gaps/invisible · theorem/audit · gate/light · wave/complete · merge/wave · feed-mo · chat/research
 */
export function chatAudit(matrix: MindMatrix = buildMatrix(), at = 0, root = typeof process !== 'undefined' && process.cwd ? process.cwd() : '.') {
  return memoByRoot(`chatAudit:${floor(at / (100 * 5 * 2))}:${root}`, matrix, () => {
    const soft = (a: string, b: string) =>
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(`${a}/${b}`) &&
      foldPair(toUuid(`cmd:${a}`), toUuid(`cmd:${b}`)).bidirectional
    const has = (id: string) => (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes(id)
    const git = collectChatWaveGitLog(root)
    const pairsFromCommits = [...new Set(git.commits.flatMap((c) => c.pairs))]
    const tipRows = CHAT_WAVE_SEALED_TIPS.map((pair) => ({
      pair,
      landed: pairsFromCommits.includes(pair) || has(pair),
      inGitLog: pairsFromCommits.includes(pair),
      inRegistry: has(pair),
    }))
    const tipsLanded = tipRows.filter((r) => r.landed).length
    const measure = measureDecide(matrix, at)
    let dupe = { computes: false, groups: 0, shellCount: 0, bodies: 0, duplicateBodies: 0 }
    try {
      const d = dryDupe(root)
      dupe = { computes: d.computes, groups: d.groups, shellCount: d.shellCount, bodies: d.bodies, duplicateBodies: d.duplicateBodies }
    } catch {
      dupe = { computes: false, groups: -1, shellCount: -1, bodies: 0, duplicateBodies: 0 }
    }
    let dryCleanOn = false
    try {
      dryCleanOn = dryCleanIsDiamondAndCrystal().diamond
    } catch {
      dryCleanOn = false
    }
    const gaps = invisibleGapsCaughtByGatesBody(matrix, at)
    const ta = theoremAudit()
    let geo = { computes: false, encodeCoverage: 0, encodeReceipts: 0, theoremsEncoded: 0 }
    try {
      const g = geoGebraEncode()
      geo = { computes: g.computes, encodeCoverage: g.encodeCoverage, encodeReceipts: g.encodeReceipts, theoremsEncoded: g.theoremsEncoded }
    } catch {
      geo = { computes: false, encodeCoverage: 0, encodeReceipts: 0, theoremsEncoded: 0 }
    }
    let gateLightReport = { computes: false, gateCost: 0, computeCoverage: 0 }
    try {
      const g = gateLight(root)
      gateLightReport = { computes: g.computes, gateCost: g.gateCost, computeCoverage: g.computeCoverage }
    } catch {
      gateLightReport = { computes: false, gateCost: 0, computeCoverage: 0 }
    }
    const wave = waveComplete(matrix, at)
    const merge = mergeWave(matrix, at)
    const research = chatResearch(matrix, at)
    const mesh = theoremMesh(matrix, at)
    const site = sitePathWave(matrix, at)
    const refactorOn =
      merge.computes &&
      merge.redundancyPurged &&
      dupe.computes &&
      dupe.groups === 0 &&
      measure.computes
    const dryCleanOnFacet =
      dryCleanOn &&
      dupe.computes &&
      dupe.groups === 0 &&
      soft('dry', 'dupe') &&
      soft('dry', 'clean')
    const gapsFilledOnWay =
      gaps.invisibleGapsCaughtByGates &&
      gaps.afterClosed >= gaps.afterOpen &&
      soft('gaps', 'invisible')
    const commitsInventoried = git.gitAvailable && git.commitCount > 0
    const metricsOn =
      measure.computes &&
      measure.observerEvaluableMeasurements &&
      ta.computes &&
      geo.computes
    const composeOn =
      soft('measure', 'decide') &&
      soft('dry', 'dupe') &&
      soft('dry', 'clean') &&
      soft('gaps', 'invisible') &&
      soft('theorem', 'audit') &&
      soft('gate', 'light') &&
      soft('wave', 'complete') &&
      soft('merge', 'wave') &&
      soft('chat', 'research') &&
      has('mo/chat')
    const honestOpenNamed = [
      `onTrueDebt=${measure.gateAnalyticsHardcodedOnCount ?? gateLightReport.gateCost} gateCost=${gateLightReport.gateCost}`,
      `theorem=${ta.theoremCount}/${ta.totalRegistry} not-theorem=${ta.notTheoremCount} ratio=${ta.ratio}`,
      `geo coverage=${geo.encodeCoverage} encoded=${geo.encodeReceipts}/432`,
      `dryDupe trueGroups=${dupe.groups} twinShell=${dupe.shellCount}`,
      `site/path covered=${site.pathsCovered ?? 0} consensus=${site.consensusWavesOn ? 1 : 0}`,
      `frontier/ui: site-path consensusWavesOn honest-open`,
      `mesh saved=${mesh.mill?.savedCount ?? 0} onWay=${mesh.discoveredRows?.length ?? 0}`,
      `wave-complete mesh=${wave.mesh?.theoremMesh ? 1 : 0} gateLight=${gateLightReport.computes ? 1 : 0}`,
      `judgmentPatternHitCount=${measure.judgmentPatternHitCount}`,
      'migrate-next: drain on:true debt · promote theorem seeds · geo encode remainder',
    ] as const
    const landedTable = [
      { class: 'commits', metric: 'chat-wave commits', landed: `${git.commitCount} (${CHAT_WAVE_AUDIT_ANCHOR}..${git.head})`, residual: git.gitAvailable ? 'none' : 'git-unavailable' },
      { class: 'tips', metric: 'sealed tips matched', landed: `${tipsLanded}/${CHAT_WAVE_SEALED_TIPS.length}`, residual: `${CHAT_WAVE_SEALED_TIPS.length - tipsLanded} tips not in git log` },
      { class: 'dry-clean', metric: 'TRUE duplicate groups', landed: `${dupe.groups}`, residual: dupe.groups > 0 ? `${dupe.groups} groups to delete` : 'queue empty' },
      { class: 'dry-clean', metric: 'twin-shell duals', landed: `${dupe.shellCount}`, residual: 'named not deleted' },
      { class: 'theorem', metric: 'registry theorem/not', landed: `${ta.theoremCount}/${ta.notTheoremCount}`, residual: `522 prose-slogan migrate-next` },
      { class: 'geo', metric: 'encode coverage', landed: `${roundTo(geo.encodeCoverage, 4)} (${geo.encodeReceipts}/432)`, residual: `${roundTo(1 - geo.encodeCoverage, 4)} open` },
      { class: 'gate', metric: 'on:true debt', landed: `${gateLightReport.gateCost}`, residual: 'migrate-next stripStrings' },
      { class: 'site', metric: 'path consensus', landed: `${site.pathsCovered ?? 0}/6`, residual: site.consensusWavesOn ? 'none' : 'consensusWavesOn open' },
      { class: 'mesh', metric: 'theorem mesh', landed: mesh.theoremMesh ? 'saved+onWay' : 'partial', residual: mesh.autosaveOn ? 'none' : 'autosave' },
      { class: 'chat', metric: 'research feed', landed: research.throughChatApi ? 'wired' : 'partial', residual: research.externalResearchOn ? 'ephemeral bootstrap only' : 'local' },
    ] as const
    const chatWorkAudited = commitsInventoried && tipsLanded >= CHAT_WAVE_SEALED_TIPS.length - 5
    const on =
      chatWorkAudited &&
      commitsInventoried &&
      metricsOn &&
      composeOn &&
      refactorOn &&
      dryCleanOnFacet &&
      gapsFilledOnWay
    const facets = [
      { facet: 'chatWorkAudited', on: chatWorkAudited },
      { facet: 'refactorOn', on: refactorOn },
      { facet: 'dryCleanOn', on: dryCleanOnFacet },
      { facet: 'gapsFilledOnWay', on: gapsFilledOnWay },
      { facet: `commitsInventoried=${git.commitCount} anchor=${CHAT_WAVE_AUDIT_ANCHOR} head=${git.head}`, on: commitsInventoried },
      { facet: `tipsLanded=${tipsLanded}/${CHAT_WAVE_SEALED_TIPS.length}`, on: tipsLanded >= CHAT_WAVE_SEALED_TIPS.length - 5 },
      { facet: 'residualNamed', on: honestOpenNamed.length >= 1 },
      { facet: 'metricsOn', on: metricsOn },
      { facet: 'compose measure/decide · dry/dupe · dry/clean · gaps/invisible · theorem/audit · gate/light · wave/complete · merge/wave · feed-mo · chat/research', on: composeOn },
    ].map((entry) => ({ ...entry, receipt: toUuid(`chat-audit:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('chat-audit-wave-inventory', facets)
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    return {
      computes: sealed.ok && commitsInventoried && metricsOn,
      chatAudit: on,
      chatWorkAudited,
      refactorOn,
      dryCleanOn: dryCleanOnFacet,
      gapsFilledOnWay,
      commitsInventoried,
      residualNamed: [...honestOpenNamed],
      metricsOn,
      git,
      tipRows,
      tipsLanded,
      landedTable: [...landedTable],
      measure,
      dupe,
      gaps,
      theorem: ta,
      geo,
      gateLight: gateLightReport,
      wave,
      merge,
      research,
      mesh,
      site,
      claySolvedByThisFold,
      physicalFtlClaim: 0 as const,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([sealed.root, git.head ? toUuid(`chat-audit:head:${git.head}`) : toUuid('chat-audit:no-git')]),
      pair: 'chat/audit' as const,
      pairs: ['chat/audit', 'audit/chat'] as const,
      dualPair: 'audit/chat' as const,
      cli: 'npm run quantum:chat-audit',
      route: '/en/quantum-tools#chat-audit',
      heading: 'Chat audit · chat-wave inventory · dry-clean · gaps',
      statement:
        `chatAudit — commits=${git.commitCount} tips=${tipsLanded}/${CHAT_WAVE_SEALED_TIPS.length} ` +
        `theorem=${ta.theoremCount}/${ta.totalRegistry} geo=${roundTo(geo.encodeCoverage, 4)} ` +
        `onTrueDebt=${gateLightReport.gateCost} dupeGroups=${dupe.groups}.`,
      boundary:
        'Measured audit of chat-wave landed work from git log (anchor tool/matrix) + composed fold receipts. ' +
        'Dry-clean Δ from dryDupe · theorem/audit census · geo/gebra coverage · gate/light on:true debt. ' +
        'Residuals honest-open — NOT fake-close Clay/FTL.',
    }
  })
}

/** npm run quantum:chat-audit */
export function runChatAuditExit(root = typeof process !== 'undefined' && process.cwd ? process.cwd() : '.', _argv: readonly string[] = []): number {
  void _argv
  const report = chatAudit(buildMatrix(), 0, root)
  process.stdout.write(`${report.computes ? '✓' : '✗'} chat-audit — ${report.statement}\n`)
  process.stdout.write(`  anchor=${CHAT_WAVE_AUDIT_ANCHOR} head=${report.git.head} commits=${report.git.commitCount}\n`)
  process.stdout.write('  landed table:\n')
  for (const row of report.landedTable) {
    process.stdout.write(`    · [${row.class}] ${row.metric}: ${row.landed} · residual=${row.residual}\n`)
  }
  process.stdout.write('  tips (sealed vs git):\n')
  for (const t of report.tipRows.filter((r) => !r.landed)) {
    process.stdout.write(`    · OPEN ${t.pair} registry=${t.inRegistry ? 1 : 0}\n`)
  }
  process.stdout.write('  honest-open:\n')
  for (const id of report.residualNamed) process.stdout.write(`    · ${id}\n`)
  for (const f of report.facets) process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  return report.computes ? 0 : 1
}

