    const sessionCaches =
      theoremFormulaWaves &&
      zeroTokenReuse &&
      soft('session', 'save') &&
      soft('session', 'live') &&
      soft('session', 'cache') &&
      soft('cache', 'theorem') &&
      soft('formula', 'cache')
    const pairS = has('session/cache')
