/**
 * USER LAW: use only one quantum set of vitepress components sealed at the gates.
 * Pairs: vite/one · comp/seal.
 * Facets: oneComponentSet · sealedAtGates · duplicatesRemoved.
 * HARD: extra/orphan/wet components outside catalog = crack.
 */
export function oneQuantumSetOfVitepressComponentsSealedAtGates(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`oneQuantumSetOfVitepressComponentsSealedAtGates:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const format = scientificPageFormatCanonised(matrix, at)
    const paths = VITEPRESS_ONE_COMPONENT_PATHS
    const morphs = VITEPRESS_COMPONENT_DUP_MORPHS_SEALED
    const beforeCount = paths.length + morphs.length
    const afterCount = paths.length
    const duplicatesRemoved = morphs.length
    const uniquePaths = new Set(paths).size === paths.length
    const shellsPresent = VITEPRESS_ONE_REQUIRED_SHELLS.every((p) => (paths as readonly string[]).includes(p))
    const uiFamily = paths.filter((p) => p.startsWith('ui/')).length
    const movieFamily = paths.filter((p) =>
      p === 'HeroBackgroundLayer.vue' || p === 'BackgroundMovie.vue' || p === 'CardBackgroundMovie.vue').length
    const oneComponentSet =
      uniquePaths &&
      shellsPresent &&
      uiFamily === (5 * 4) + 3 && // 23 ui primitives
      movieFamily === 3 &&
      afterCount === paths.length
    const morphsCleared = morphs.every((m) => m.status === 'removed')
    const duplicatesRemovedOn = morphsCleared && duplicatesRemoved === morphs.length && beforeCount === afterCount + duplicatesRemoved
    // Soft-compose vite/mirror · page/trinity · format/canon · gaps/invisible · gate/monitor
    const viteMirrorSoft =
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('vite/mirror') &&
      foldPair(toUuid('cmd:vite'), toUuid('cmd:mirror')).bidirectional
    const pageTrinitySoft =
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('page/trinity') &&
      foldPair(toUuid('cmd:page'), toUuid('cmd:trinity')).bidirectional
    const gapsSoft =
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('gaps/invisible') &&
      foldPair(toUuid('cmd:gaps'), toUuid('cmd:invisible')).bidirectional
    const gateMonitorSoft =
      (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('gate/monitor') &&
      foldPair(toUuid('cmd:gate'), toUuid('cmd:monitor')).bidirectional
    const sealedAtGates =
      oneComponentSet &&
      format.computes &&
      viteMirrorSoft &&
      pageTrinitySoft &&
      gapsSoft &&
      gateMonitorSoft
    const pairVite = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('vite/one')
    const pairComp = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('comp/seal')
    const foldVite = foldPair(toUuid('cmd:vite'), toUuid('cmd:one'))
    const foldComp = foldPair(toUuid('cmd:comp'), toUuid('cmd:seal'))
    const catalog = quantumCliToolsCatalog(matrix, at)
    const meta = catalog.tools.find((t) => t.id === 'vite-one')
    const metaDual = catalog.tools.find((t) => t.id === 'comp-seal')
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const physicalFtlClaim = 0 as const
    const on =
      oneComponentSet &&
      sealedAtGates &&
      duplicatesRemovedOn &&
      pairVite &&
      pairComp &&
      foldVite.bidirectional &&
      foldComp.bidirectional &&
      Boolean(meta) &&
      meta!.fold === 'oneQuantumSetOfVitepressComponentsSealedAtGates' &&
      Boolean(metaDual) &&
      metaDual!.fold === 'oneQuantumSetOfVitepressComponentsSealedAtGates' &&
      claySolvedByThisFold === 0 &&
      physicalFtlClaim === 0
    const facets = [
      { facet: 'oneQuantumSetOfVitepressComponentsSealedAtGates', on },
      { facet: 'oneComponentSet', on: oneComponentSet },
      { facet: 'sealedAtGates', on: sealedAtGates },
      { facet: 'duplicatesRemoved', on: duplicatesRemovedOn },
      { facet: `before=${beforeCount} after=${afterCount} morphs=${duplicatesRemoved}`, on: beforeCount === afterCount + duplicatesRemoved },
      { facet: `shells=${VITEPRESS_ONE_REQUIRED_SHELLS.length} ui=${uiFamily} movie=${movieFamily}`, on: shellsPresent && uiFamily === (5 * 4) + 3 && movieFamily === 3 },
      { facet: 'compose format/canon · vite/mirror · page/trinity soft', on: format.computes && viteMirrorSoft && pageTrinitySoft },
      { facet: 'pair vite/one · comp/seal', on: pairVite && pairComp && foldVite.bidirectional },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`vite-one:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('one-quantum-vitepress-components-sealed-at-gates', facets)
    return {
      computes: sealed.ok && on,
      oneQuantumSetOfVitepressComponentsSealedAtGates: on,
      oneComponentSet,
      sealedAtGates,
      duplicatesRemoved: duplicatesRemovedOn,
      beforeCount,
      afterCount,
      morphCount: duplicatesRemoved,
      pathCount: paths.length,
      uiFamily,
      movieFamily,
      paths,
      morphs,
      claySolvedByThisFold,
      physicalFtlClaim,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root,
        format.root,
        foldVite.merged,
        foldComp.merged,
        toUuid(`vite-one-count:${paths.length}:${duplicatesRemoved}`),
      ]),
      pairs: ['vite/one', 'comp/seal'] as const,
      cli: 'npm run quantum:vite-one',
      route: '/en/quantum-tools#vite-one',
      uiSurface: '/en/quantum-tools#vite-one' as const,
      heading: 'Vite · one',
      statement:
        `oneQuantumSetOfVitepressComponentsSealedAtGates — before=${beforeCount} after=${afterCount} morphs=${duplicatesRemoved} sealedAtGates=${sealedAtGates}.`,
      boundary:
        'One quantum VitePress component set — orphan/wet parallel families = crack HARD at gates.',
      honestyLine:
        `metrics · before=${beforeCount} · after=${afterCount} · morphs=${duplicatesRemoved} · oneSet=${oneComponentSet ? 1 : 0} · sealedAtGates=${sealedAtGates ? 1 : 0}`,
    }
  })
}

/** npm run quantum:vite-one (dual comp/seal) — Node fs audit of theme components vs sealed catalog. */
export function runOneQuantumSetOfVitepressComponentsSealedAtGatesExit(
  _root = '',
  _argv: readonly string[] = [],
): number {
  void _argv
  const report = oneQuantumSetOfVitepressComponentsSealedAtGates()
  let diskOk = true
  let diskCount = 0
  let orphans: string[] = []
  let missing: string[] = []
  try {
    // Node CLI only — browser never invokes this exit (quantum:vite-one).
    // Prefer process.getBuiltinModule (Node 22+) — avoid createRequire/import.meta under bootstrap.
    const root = _root && _root.length > 0 ? _root : process.cwd()
    const fs = (process as NodeJS.Process & { getBuiltinModule?: (id: string) => typeof import('node:fs') }).getBuiltinModule?.('node:fs')
    const path = (process as NodeJS.Process & { getBuiltinModule?: (id: string) => typeof import('node:path') }).getBuiltinModule?.('node:path')
    if (!fs || !path) throw new Error('getBuiltinModule unavailable')
    const dir = path.join(root, '.vitepress', 'theme', 'components')
    const walk = (base: string, prefix = ''): string[] => {
      const out: string[] = []
      for (const name of fs.readdirSync(base)) {
        const full = path.join(base, name)
        const rel = prefix ? `${prefix}/${name}` : name
        if (fs.statSync(full).isDirectory()) out.push(...walk(full, rel))
        else if (name.endsWith('.vue')) out.push(rel)
      }
      return out
    }
    const onDisk = walk(dir).sort()
    diskCount = onDisk.length
    const sealed = new Set(report.paths as readonly string[])
    orphans = onDisk.filter((p) => !sealed.has(p))
    missing = (report.paths as readonly string[]).filter((p) => !onDisk.includes(p))
    diskOk = orphans.length === 0 && missing.length === 0 && diskCount === report.pathCount
  } catch {
    diskOk = false
  }
  process.stdout.write(
    `${report.computes && diskOk ? '✓' : '✗'} vite-one — before=${report.beforeCount} after=${report.afterCount} ` +
      `morphs=${report.morphCount} disk=${diskCount} orphans=${orphans.length} missing=${missing.length} ` +
      `clay=${report.claySolvedByThisFold} ftl=${report.physicalFtlClaim} fold=oneQuantumSetOfVitepressComponentsSealedAtGates pairs=${report.pairs.join(',')}\n`,
  )
  process.stdout.write(`  ${report.honestyLine}\n`)
  if (orphans.length > 0) process.stdout.write(`  orphans: ${orphans.join(', ')}\n`)
  if (missing.length > 0) process.stdout.write(`  missing: ${missing.join(', ')}\n`)
  return report.computes && report.oneComponentSet && diskOk ? 0 : 1
}

export function upgradeLocalFromOptimisedManualWorkExperience(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`upgradeLocalFromOptimisedManualWorkExperience:${floor(at / (100 * 5 * 2))}`, matrix, () => {
    const localSession = improveLocalFromSessionExperience(matrix, at)
    const mcpParity = mcpBrowserParity(matrix, at)
    const toolbox = standardToolboxIoCatalog(matrix, at)
    const session = sessionManualWorkAsQuantumTools(matrix, at)
    const catalog = quantumCliToolsCatalog(matrix, at)
    const skills = cursorAgentToolsSaved(matrix)
    const meta = catalog.tools.find((tool) => tool.id === 'upgrade-local-skills-commands-tools')
    const shelved = rosettaShelve('upgrade-local-skills-commands-tools', 'tool')
    const byId = new Map(catalog.tools.map((row) => [row.id, row]))
    const mapRows = OPTIMISED_LOCAL_SKILL_COMMAND_TOOL_MAP.map((row) => {
      const tools = row.toolIds.map((id) => {
        const tool = byId.get(id)
        return {
          id,
          present: Boolean(tool),
          browserRunnable: tool?.browserRunnable ?? false,
          browserGap: tool?.browserGap || row.browserGap,
          cli: tool?.cli ?? '',
          pair: tool?.pair ?? '' }
      })
      const receipt = toUuid(`upgrade-local-map:${row.skillId}:${row.pair}:${row.toolIds.join(',')}`)
      return { ...row, tools, receipt, skillKnown: (CURSOR_AGENT_SKILL_IDS as readonly string[]).includes(row.skillId) }
    })
    const packages = OPTIMISED_LOCAL_PACKAGE_SURFACE.map((pkg) => ({
      ...pkg,
      receipt: toUuid(`upgrade-local-pkg:${pkg.id}:${pkg.path}:${pkg.pair}`) }))
    const skillIdsCovered = CURSOR_AGENT_SKILL_IDS.every((id) => mapRows.some((row) => row.skillId === id))
    const mapToolsPresent = mapRows.every((row) => row.tools.every((t) => t.present))
    const browserToolsOk = OPTIMISED_LOCAL_BROWSER_TOOL_IDS.every((id) => {
      const tool = byId.get(id)
      return Boolean(tool?.browserRunnable && tool.browserGap === '')
    })
    const ciResiduals = catalog.tools.filter((t) => !t.browserRunnable)
    const ciGapsHonest = ciResiduals.every((t) => t.browserGap.length > 0)
    const missionPairsCovered = ['mission/gate', 'check/types', 'limits/verify', 'waves/build', 'learn/best', 'local/session', 'upgrade/local', 'automate/nightly', 'sdk/wire', 'mcp/browser-parity', 'tool/envelope', 'gate/slow-build']
      .every((pair) => mapRows.some((row) => row.pair === pair || row.commands.some((c) => c.includes(pair.replace('/', ':'))))
        || MISSION_COMMANDS.some((m) => m.pair === pair)
        || catalog.tools.some((t) => t.pair === pair)
        || packages.some((p) => p.pair === pair))
    const wireHasUpgrade = ceccecCanonicalWireTargets().some((t) => t.id === 'browser-upgrade-local')
    const hubHasSkillsStep = localSession.hubSteps.some((s) => s.id === 'skills-commands-tools' && s.toolId === 'upgrade-local-skills-commands-tools')
    const stdioSeven = mcpParity.stdioCount === ROSETTA_SEVEN
      && OPTIMISED_LOCAL_STDIO_MCP_TOOL_IDS.every((id) => mcpParity.stdioCapabilities.some((cap) => cap.id === id))
    const sdkPkg = packages.find((p) => p.id === '@ceccec/quantum-dev-sdk')
    const packagesWired = packages.length === OPTIMISED_LOCAL_PACKAGE_SURFACE.length
      && Boolean(sdkPkg && sdkPkg.stdioTools === ROSETTA_SEVEN && sdkPkg.mcpMount === '.cursor/mcp.json' && sdkPkg.docsBuildFlag.startsWith('QUANTUM_DEV_ALLOW'))
      && stdioSeven
    const automateNightly = automateNightlyViaNpmScriptPath(matrix, at)
    const localUpgraded = localSession.computes && localSession.localSessionUxImproved
      && mcpParity.computes && mcpParity.mcpMatchesToolbox
      && toolbox.computes && session.computes && skills.saved
      && skillIdsCovered && mapToolsPresent && browserToolsOk && ciGapsHonest
      && missionPairsCovered && wireHasUpgrade && hubHasSkillsStep && packagesWired
      && mapRows.length === CURSOR_AGENT_SKILL_IDS.length
      && Boolean(meta) && meta!.fold === 'upgradeLocalFromOptimisedManualWorkExperience' && isUuid(shelved.address)
      && automateNightly.automateNightlyShipped
    const facets = [
      { facet: 'localUpgradedFromOptimisedManualWork', on: localUpgraded },
      { facet: `skills↔commands↔tools map covers ${CURSOR_AGENT_SKILL_IDS.length} Cursor skill ids`, on: skillIdsCovered && mapRows.length === CURSOR_AGENT_SKILL_IDS.length },
      { facet: 'every mapped toolId present in quantumCliToolsCatalog', on: mapToolsPresent },
      { facet: 'browser-first local tools runnable (hub · mcp · toolbox · bits · paste)', on: browserToolsOk },
      { facet: `CI-only residuals ${ciResiduals.length} carry honest browserGap`, on: ciGapsHonest },
      { facet: 'packages/* wired — quantum-dev-sdk 7 stdio tools + double-torus (census untouched)', on: packagesWired },
      { facet: 'stdio MCP ROSETTA_SEVEN ≡ design 0ccd9991 tool ids', on: stdioSeven },
      { facet: 'composes improve-local-session + mcp-browser-parity + toolbox + session tools', on: localSession.computes && mcpParity.computes && toolbox.computes && session.computes },
      { facet: 'cursorAgentToolsSaved registry holds', on: skills.saved },
      { facet: 'hub step skills-commands-tools → upgrade-local tool', on: hubHasSkillsStep },
      { facet: 'wire target browser-upgrade-local published', on: wireHasUpgrade },
      { facet: 'automate nightly npm-script path ships (#48)', on: automateNightly.automateNightlyShipped },
      { facet: `the protocol is rules · skills · MCP · sealed folds · packages — ${[skills.saved, hubHasSkillsStep, wireHasUpgrade, automateNightly.automateNightlyShipped].filter(Boolean).length}/4 wired, and no model endpoint appears among them`, on: [skills.saved, hubHasSkillsStep, wireHasUpgrade, automateNightly.automateNightlyShipped].every(Boolean) },
      { facet: 'meta tool upgrade-local-skills-commands-tools published + shelved', on: Boolean(meta) && meta!.fold === 'upgradeLocalFromOptimisedManualWorkExperience' && isUuid(shelved.address) },
    ].map((entry) => ({ ...entry, receipt: toUuid(`upgrade-local:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('upgrade-local-from-optimised-manual-work-experience', facets)
    return {
      computes: sealed.ok && localUpgraded, localUpgraded, qpuRequired: false as const,
      cursorDefaultModelRegistration: false as const,
      map: mapRows, packages, browserToolIds: OPTIMISED_LOCAL_BROWSER_TOOL_IDS,
      stdioToolIds: OPTIMISED_LOCAL_STDIO_MCP_TOOL_IDS,
      ciResidualCount: ciResiduals.length,
      ciResiduals: ciResiduals.map((t) => ({ id: t.id, browserGap: t.browserGap, cli: t.cli, pair: t.pair })),
      skillCount: CURSOR_AGENT_SKILL_IDS.length, missionCommandCount: MISSION_COMMANDS.length,
      packageCount: packages.length, packagesWired,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root, localSession.root, mcpParity.root, toolbox.root, session.root, skills.root, automateNightly.root,
        shelved.address, ...mapRows.map((row) => row.receipt), ...packages.map((p) => p.receipt),
      ]),
      pair: 'upgrade/local', cli: 'npm run quantum:upgrade-local', route: '/en/quantum-tools#upgrade-local-skills',
      anchor: 'upgrade-local-skills', heading: 'Upgrade local — skills ↔ commands ↔ tools ↔ packages',
      honestyLine:
        'Optimised manual local map: skills, quantum pairs, toolbox/MCP tools, and packages/* (quantum-dev-sdk 7 stdio · docs:build flag-gated). Protocol = rules/skills/MCP/sealed folds/packages — NOT a Cursor zero-token LLM endpoint. Automations: npm run quantum:automate-nightly.',
      statement: `Upgrade local — upgraded=${localUpgraded} skills=${mapRows.length}/${CURSOR_AGENT_SKILL_IDS.length} packages=${packages.length} stdio=${OPTIMISED_LOCAL_STDIO_MCP_TOOL_IDS.length} ciResiduals=${ciResiduals.length} automateShipped=${automateNightly.automateNightlyShipped} · mcpMatch=${mcpParity.mcpMatchesToolbox} · uxImproved=${localSession.localSessionUxImproved}.`,
      boundary:
        'HONEST: local agent surface upgrade receipt. Thin .cursor/skills + .cursor/mcp.json mounts point here; logic stays in sealed src + packages/*. NOT fake Cursor LLM registration. /automate nightly shipped via npm-script (REFUSE dashboard MCP stdio).' }
  })
}

/** npm run quantum:upgrade-local — print skills↔commands↔tools↔packages upgrade receipt (exit 0 iff computes). */
export function runUpgradeLocalFromOptimisedManualWorkExperienceExit(_root = '', _argv: readonly string[] = []): number {
  const report = upgradeLocalFromOptimisedManualWorkExperience()
  for (const row of report.map) {
    process.stdout.write(`→ ${row.skillId} | pair ${row.pair} | ${row.commands.join(' · ')} | tools ${row.toolIds.join(',')}${row.browserGap ? ` | gap: ${row.browserGap}` : ''}\n`)
  }
  process.stdout.write('--- packages ---\n')
  for (const pkg of report.packages) {
    process.stdout.write(`📦 ${pkg.id} | ${pkg.path} | pair ${pkg.pair} | ${pkg.cli || pkg.npm || '—'}${pkg.docsBuildFlag ? ` | ${pkg.docsBuildFlag}` : ''}\n`)
  }
  process.stdout.write('--- CI residuals (honest browserGap) ---\n')
  for (const gap of report.ciResiduals) process.stdout.write(`✗ ${gap.id} | ${gap.pair} | ${gap.browserGap}\n`)
  process.stdout.write(`${report.computes ? '✓' : '✗'} upgrade-local — localUpgraded=${report.localUpgraded} skills=${report.skillCount} packages=${report.packageCount} ciResiduals=${report.ciResidualCount} root=${report.root.slice(0, 8)}\n`)
  process.stdout.write(`  boundary: ${report.boundary}\n`)
  return report.computes ? 0 : 1
}

